import { GoogleGenAI } from "@google/genai";
import { BibleRequest, TTSRequest } from "../types";
import { base64ToUint8Array, createWavBlob } from "../utils/audioUtils";

// Helper to split text into manageable chunks for TTS
const chunkText = (text: string, maxLength: number = 2800): string[] => {
  if (text.length <= maxLength) return [text];

  const chunks: string[] = [];
  let current = text;

  while (current.length > 0) {
    if (current.length <= maxLength) {
      chunks.push(current);
      break;
    }

    // Try to split at the last period within the limit to keep sentences intact
    let splitIndex = current.lastIndexOf('. ', maxLength);

    // Fallback to any space if no period found
    if (splitIndex === -1) {
      splitIndex = current.lastIndexOf(' ', maxLength);
    }

    // Hard split if no spaces found (unlikely in normal text)
    if (splitIndex === -1) {
      splitIndex = maxLength;
    }

    const chunk = current.slice(0, splitIndex + 1);
    chunks.push(chunk);

    current = current.slice(splitIndex + 1).trim();
  }

  return chunks;
};

/**
 * Generates audio from a string of text using Gemini TTS.
 */
export const generateAudioFromText = async (text: string, voice: string): Promise<Blob> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const textChunks = chunkText(text);
  const audioBuffers: Uint8Array[] = [];

  console.log(`Processing ${textChunks.length} text chunks with voice: ${voice}`);

  try {
    for (let i = 0; i < textChunks.length; i++) {
      const chunk = textChunks[i];
      if (!chunk) continue;

      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: {
          parts: [{ text: chunk }]
        },
        config: {
          responseModalities: ['AUDIO'], 
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: voice },
            },
          },
        },
      });

      const candidate = response.candidates?.[0];
      const base64Audio = candidate?.content?.parts?.[0]?.inlineData?.data;

      if (!base64Audio) {
        if (candidate?.finishReason && candidate.finishReason !== 'STOP') {
            throw new Error(`Generation stopped for chunk ${i+1} due to: ${candidate.finishReason}`);
        }
        throw new Error(`No audio data returned for part ${i + 1}.`);
      }

      audioBuffers.push(base64ToUint8Array(base64Audio));
    }

    const totalLength = audioBuffers.reduce((acc, buf) => acc + buf.length, 0);
    const combinedPCM = new Uint8Array(totalLength);
    let offset = 0;

    for (const buf of audioBuffers) {
      combinedPCM.set(buf, offset);
      offset += buf.length;
    }

    return createWavBlob(combinedPCM, 24000);

  } catch (error: any) {
    console.error("Gemini TTS Error:", error);
    throw new Error(error.message || "Failed to generate audio.");
  }
};

export const generateBibleAudio = async (request: BibleRequest): Promise<Blob> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const textPrompt = `
    Please provide the full text of the Bible chapter: ${request.book} Chapter ${request.chapter} in the ${request.version}.

    Formatting Requirements for Text-to-Speech:
    - Output ONLY the scripture text.
    - Do NOT include verse numbers.
    - Do NOT include footnotes, cross-references, or introductions.
    - Text should be continuous and readable.

    If the requested version is restricted by copyright, provide the King James Version (KJV) instead.
  `;

  let scriptureText = '';

  try {
    const textResponse = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: textPrompt,
    });

    const candidate = textResponse.candidates?.[0];

    if (candidate) {
        if (candidate.finishReason === 'SAFETY') {
            throw new Error("Request blocked by safety filters.");
        }
        if (candidate.finishReason === 'RECITATION') {
            throw new Error("Request blocked due to copyright. Please use the King James Version (KJV).");
        }
    }

    scriptureText = textResponse.text || '';
    scriptureText = scriptureText.replace(/^```(text)?/i, '').replace(/```$/, '').trim();

    if (!scriptureText) {
        if (candidate?.content?.parts?.[0]?.text) {
             scriptureText = candidate.content.parts[0].text;
        } else {
             throw new Error(`The model returned no text.`);
        }
    }

  } catch (error: any) {
      console.error("Text Retrieval Error:", error);
      throw new Error(`Failed to retrieve scripture text: ${error.message}`);
  }

  const fullTextToSpeak = `${request.book} Chapter ${request.chapter}. ${scriptureText}`;
  return generateAudioFromText(fullTextToSpeak, request.voice);
};

export const generateVoicePreview = async (voice: string): Promise<Blob> => {
  const previewText = "The Lord is my shepherd; I shall not want.";
  return generateAudioFromText(previewText, voice);
};

import React, { useState } from 'react';
import { TTSRequest, VOICE_OPTIONS, SPEED_OPTIONS } from '../types';
import { Volume2, Loader2, ChevronDown, PlayCircle, PauseCircle, Type, Mic } from 'lucide-react';
import { generateVoicePreview } from '../services/geminiService';

interface SimpleTTSFormProps {
  data: TTSRequest;
  onChange: (data: TTSRequest) => void;
  onSubmit: () => void;
  onSwitchMode: () => void;
  isLoading: boolean;
}

const SimpleTTSForm: React.FC<SimpleTTSFormProps> = ({ data, onChange, onSubmit, onSwitchMode, isLoading }) => {
  const [previewLoading, setPreviewLoading] = useState(false);
  const [previewPlaying, setPreviewPlaying] = useState(false);
  const [currentPreviewAudio, setCurrentPreviewAudio] = useState<HTMLAudioElement | null>(null);

  const updateField = (field: keyof TTSRequest, value: any) => {
      onChange({
          ...data,
          [field]: value
      });
  };

  const handlePreviewVoice = async (e: React.MouseEvent) => {
    e.preventDefault();
    if (previewPlaying && currentPreviewAudio) {
      currentPreviewAudio.pause();
      setPreviewPlaying(false);
      return;
    }
    setPreviewLoading(true);
    try {
      const blob = await generateVoicePreview(data.voice);
      const url = URL.createObjectURL(blob);
      const audio = new Audio(url);
      audio.onended = () => {
        setPreviewPlaying(false);
        URL.revokeObjectURL(url);
      };
      audio.play();
      setCurrentPreviewAudio(audio);
      setPreviewPlaying(true);
    } catch (err) {
      console.error("Preview failed", err);
    } finally {
      setPreviewLoading(false);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (data.text.trim() && data.voice) {
        if (currentPreviewAudio) {
            currentPreviewAudio.pause();
            setPreviewPlaying(false);
        }
        onSubmit();
    }
  };

  const currentVoiceIsPredefined = VOICE_OPTIONS.some(v => v.id === data.voice);
  const selectValue = currentVoiceIsPredefined ? data.voice : 'custom';

  return (
    <div className="w-full max-w-xl mx-auto bg-slate-800/50 p-8 rounded-2xl border border-slate-700 shadow-xl backdrop-blur-sm">
      <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-bold text-amber-100 cinzel">Generic Inscription</h2>
          <button 
            type="button" 
            onClick={onSwitchMode}
            className="text-xs text-amber-500/60 hover:text-amber-500 transition-colors uppercase tracking-widest border border-amber-500/20 px-3 py-1 rounded-full"
          >
            Switch to Chapters
          </button>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="space-y-2">
            <label className="block text-sm font-medium text-amber-100/80 uppercase tracking-wide">
                Manuscript Text
            </label>
            <div className="relative">
                <textarea
                    value={data.text}
                    onChange={(e) => updateField('text', e.target.value)}
                    placeholder="Enter the words to be forged into audio..."
                    className="w-full bg-slate-900/80 border border-slate-600 rounded-lg px-4 py-3 text-amber-50 focus:outline-none focus:ring-2 focus:ring-amber-500/50 transition-all min-h-[160px] resize-none"
                    required
                />
                <Type className="absolute right-3 bottom-3 text-slate-600 w-5 h-5 pointer-events-none" />
            </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-2">
            <label className="block text-sm font-medium text-amber-100/80 uppercase tracking-wide">Voice</label>
            <div className="flex flex-col gap-2">
              <div className="flex gap-2">
                <div className="relative flex-grow">
                  <select
                    value={selectValue}
                    onChange={(e) => {
                        const val = e.target.value;
                        if (val === 'custom') updateField('voice', '');
                        else updateField('voice', val);
                    }}
                    className="w-full bg-slate-900/80 border border-slate-600 rounded-lg px-4 py-3 text-amber-50 focus:outline-none focus:ring-2 focus:ring-amber-500/50 transition-all appearance-none cursor-pointer"
                  >
                    <optgroup label="Male Voices">
                        {VOICE_OPTIONS.filter(v => v.gender === 'Male').map((v) => (
                        <option key={v.id} value={v.id}>{v.label}</option>
                        ))}
                    </optgroup>
                    <optgroup label="Female Voices">
                        {VOICE_OPTIONS.filter(v => v.gender === 'Female').map((v) => (
                        <option key={v.id} value={v.id}>{v.label}</option>
                        ))}
                    </optgroup>
                    <option value="custom">Custom ID...</option>
                  </select>
                  <ChevronDown className="absolute right-3 top-1/2 transform -translate-y-1/2 text-slate-400 w-4 h-4 pointer-events-none" />
                </div>
                <button
                  type="button"
                  onClick={handlePreviewVoice}
                  disabled={previewLoading || !data.voice}
                  className="px-3 bg-slate-700 hover:bg-slate-600 border border-slate-600 rounded-lg text-amber-500 transition-colors flex items-center justify-center disabled:opacity-50"
                  title="Preview Voice"
                >
                  {previewLoading ? <Loader2 className="w-5 h-5 animate-spin" /> : previewPlaying ? <PauseCircle className="w-5 h-5" /> : <PlayCircle className="w-5 h-5" />}
                </button>
              </div>
              {selectValue === 'custom' && (
                  <div className="relative">
                    <input 
                        type="text"
                        value={data.voice}
                        onChange={(e) => updateField('voice', e.target.value)}
                        placeholder="Voice ID..."
                        className="w-full bg-slate-800 border border-slate-500 rounded-lg px-4 py-2 text-sm text-amber-50"
                    />
                    <Mic className="absolute right-3 top-1/2 transform -translate-y-1/2 text-slate-500 w-4 h-4" />
                  </div>
              )}
            </div>
          </div>

          <div className="space-y-2">
            <label className="block text-sm font-medium text-amber-100/80 uppercase tracking-wide">Speed</label>
            <div className="relative">
              <select
                value={data.speed}
                onChange={(e) => updateField('speed', parseFloat(e.target.value))}
                className="w-full bg-slate-900/80 border border-slate-600 rounded-lg px-4 py-3 text-amber-50 focus:outline-none focus:ring-2 focus:ring-amber-500/50 transition-all appearance-none cursor-pointer"
              >
                {SPEED_OPTIONS.map((s) => (
                  <option key={s.value} value={s.value}>{s.label}</option>
                ))}
              </select>
              <ChevronDown className="absolute right-3 top-1/2 transform -translate-y-1/2 text-slate-400 w-4 h-4 pointer-events-none" />
            </div>
          </div>
        </div>

        <button
          type="submit"
          disabled={isLoading || !data.text.trim() || !data.voice}
          className={`w-full flex items-center justify-center space-x-2 py-4 rounded-lg font-bold text-lg tracking-wide transition-all duration-300 
            ${isLoading || !data.text.trim() || !data.voice
              ? 'bg-slate-700 text-slate-400 cursor-not-allowed' 
              : 'bg-gradient-to-r from-amber-600 to-amber-700 hover:from-amber-500 hover:to-amber-600 text-white shadow-[0_0_20px_rgba(217,119,6,0.4)]'
            }`}
        >
          {isLoading ? (
            <>
              <Loader2 className="animate-spin w-5 h-5" />
              <span>Forging Manuscript...</span>
            </>
          ) : (
            <>
              <Volume2 className="w-5 h-5" />
              <span>Forge Audio</span>
            </>
          )}
        </button>
      </form>
    </div>
  );
};

export default SimpleTTSForm;

