                  blob={audioState.blob}
                  title={currentTitle}
                  playbackRate={mode === 'bible' ? formData.speed : simpleData.speed}
                  onReset={handleReset}
              />
            </div>
          )}

          {audioState.isLoading && !audioState.audioUrl && (
             <div className="absolute inset-0 flex flex-col items-center justify-center z-50">
                 <div className="bg-black/40 backdrop-blur-sm p-8 rounded-2xl border border-zinc-800 shadow-2xl">
                   <p className="text-zinc-400 font-cinzel text-xl tracking-widest animate-pulse">FORGING AUDIO</p>
                   <p className="text-zinc-600 text-sm mt-3 text-center">Consulting the archives...</p>
                 </div>
             </div>
          )}
        </div>
      </main>

      <footer className="absolute bottom-4 w-full text-center text-zinc-800 text-xs tracking-widest uppercase opacity-60">
          <p>Testament of Steel • Powered by Gemini 2.5</p>
      </footer>
    </div>
  );
};

