            <label className="block text-sm font-medium text-amber-100/80 uppercase tracking-wide">
                Manuscript Text
            </label>
            <div className="relative">
                <textarea
                    value={data.text}
                    onChange={(e) => updateField('text', e.target.value)}
                    placeholder="Enter words to be forged..."
                    className="w-full bg-slate-900/80 border border-slate-600 rounded-lg px-4 py-3 text-amber-50 focus:outline-none focus:ring-2 focus:ring-amber-500/50 min-h-[120px] resize-none"
                    required
                />
                <Type className="absolute right-3 bottom-3 text-slate-600 w-5 h-5 pointer-events-none" />
            </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
