                        const val = e.target.value;
                        if (val === 'custom') updateField('voice', '');
                        else updateField('voice', val);
                    }}
                    className="w-full bg-slate-900/80 border border-slate-600 rounded-lg px-4 py-3 text-amber-50 appearance-none cursor-pointer"
                  >
                    <optgroup label="Male Voices">
                        {VOICE_OPTIONS.filter(v => v.gender === 'Male').map((v) => (
                        <option key={v.id} value={v.id}>{v.label}</option>
