                >
                  {previewLoading ? <Loader2 className="w-5 h-5 animate-spin" /> : previewPlaying ? <PauseCircle className="w-5 h-5" /> : <PlayCircle className="w-5 h-5" />}
                </button>
              </div>
              {selectValue === 'custom' && (
