import React, { useState } from 'react';
import Header from './components/Header';
import BibleForm from './components/BibleForm';
import SimpleTTSForm from './components/SimpleTTSForm';
import AudioPlayer from './components/AudioPlayer';
import { BibleRequest, TTSRequest, AudioState, BibleVersion, VOICE_OPTIONS } from './types';
import { generateBibleAudio, generateAudioFromText } from './services/geminiService';
import { AlertCircle } from 'lucide-react';
import { BIBLE_DATA } from './utils/bibleData';

const App: React.FC = () => {
  const [mode, setMode] = useState<'bible' | 'simple'>('bible');
  const [formData, setFormData] = useState<BibleRequest>({
    book: '',
    chapter: '',
    version: BibleVersion.NKJV,
    voice: VOICE_OPTIONS[0].id,
    speed: 1.0,
    pitch: 1.0
  });

  const [simpleData, setSimpleData] = useState<TTSRequest>({
    text: '',
    voice: VOICE_OPTIONS[0].id,
    speed: 1.0,
    pitch: 1.0
  });

  const [audioState, setAudioState] = useState<AudioState>({
    isLoading: false,
    audioUrl: null,
    error: null,
    blob: null
  });
  const [currentTitle, setCurrentTitle] = useState<string>('');

  const handleBibleSubmit = async () => {
    setAudioState({ isLoading: true, audioUrl: null, error: null, blob: null });
    setCurrentTitle(`${formData.book} Chapter ${formData.chapter}`);

    try {
      const blob = await generateBibleAudio(formData);
      const url = URL.createObjectURL(blob);
      setAudioState({
        isLoading: false,
        audioUrl: url,
        error: null,
        blob: blob
      });
    } catch (err: any) {
      setAudioState({
        isLoading: false,
        audioUrl: null,
        error: err.message || "An unexpected error occurred.",
        blob: null
      });
    }
  };

  const handleSimpleSubmit = async () => {
    setAudioState({ isLoading: true, audioUrl: null, error: null, blob: null });
    setCurrentTitle(`Custom Inscription`);

    try {
      const blob = await generateAudioFromText(simpleData.text, simpleData.voice, simpleData.speed, simpleData.pitch);
      const url = URL.createObjectURL(blob);
      setAudioState({
        isLoading: false,
        audioUrl: url,
        error: null,
        blob: blob
      });
    } catch (err: any) {
      setAudioState({
        isLoading: false,
        audioUrl: null,
        error: err.message || "An unexpected error occurred.",
        blob: null
      });
    }
  };

  const handleReset = () => {
    if (audioState.audioUrl) {
      URL.revokeObjectURL(audioState.audioUrl);
    }

    if (mode === 'bible' && formData.book && formData.chapter) {
      const maxChapters = BIBLE_DATA[formData.book];
      const currentChapNum = parseInt(formData.chapter, 10);
      if (currentChapNum < maxChapters) {
        setFormData(prev => ({
          ...prev,
          chapter: String(currentChapNum + 1)
        }));
      }
    }

    setAudioState({
      isLoading: false,
      audioUrl: null,
      error: null,
      blob: null
    });
    setCurrentTitle('');
  };

  const toggleMode = () => {
      setMode(prev => prev === 'bible' ? 'simple' : 'bible');
      setAudioState({ isLoading: false, audioUrl: null, error: null, blob: null });
  };

  return (
    <div className="min-h-screen bg-[radial-gradient(ellipse_at_top,_var(--tw-gradient-stops))] from-gray-900 via-black to-black text-slate-200 flex flex-col overflow-hidden">
      <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/stardust.png')] opacity-10 pointer-events-none mix-blend-overlay"></div>

      <Header />

