import React, { useRef, useState, useEffect } from 'react';
import { Play, Pause, Download, RefreshCcw, Music, FastForward } from 'lucide-react';
import { VOICE_OPTIONS } from '../types';

interface AudioPlayerProps {
  audioUrl: string;
  blob: Blob;
  title: string;
  params: {
      voice: string;
      speed: number;
      pitch: number;
  };
  onReset: () => void;
}

const AudioPlayer: React.FC<AudioPlayerProps> = ({ audioUrl, blob, title, params, onReset }) => {
  const audioRef = useRef<HTMLAudioElement>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [progress, setProgress] = useState(0);
  const [duration, setDuration] = useState(0);

  const voiceLabel = VOICE_OPTIONS.find(v => v.id === params.voice)?.label || params.voice;

  useEffect(() => {
    const audio = audioRef.current;
    if (!audio) return;

    // We don't change playbackRate here because speed is forged into the audio by Gemini
    audio.playbackRate = 1.0; 

    const updateProgress = () => {
      setProgress((audio.currentTime / audio.duration) * 100);
    };

    const onLoadedMetadata = () => {
        setDuration(audio.duration);
    }

    const onEnded = () => {
      setIsPlaying(false);
      setProgress(100);
    };

    audio.addEventListener('timeupdate', updateProgress);
    audio.addEventListener('loadedmetadata', onLoadedMetadata);
    audio.addEventListener('ended', onEnded);

    return () => {
      audio.removeEventListener('timeupdate', updateProgress);
      audio.removeEventListener('loadedmetadata', onLoadedMetadata);
      audio.removeEventListener('ended', onEnded);
    };
  }, [audioUrl]);

  const togglePlay = () => {
    if (audioRef.current) {
      if (isPlaying) {
        audioRef.current.pause();
      } else {
        audioRef.current.play();
      }
      setIsPlaying(!isPlaying);
    }
  };

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (audioRef.current) {
      const newTime = (Number(e.target.value) / 100) * audioRef.current.duration;
      audioRef.current.currentTime = newTime;
      setProgress(Number(e.target.value));
    }
  };

  const formatTime = (time: number) => {
      if (isNaN(time)) return "00:00";
      const minutes = Math.floor(time / 60);
      const seconds = Math.floor(time % 60);
      return `${minutes}:${seconds < 10 ? '0' + seconds : seconds}`;
  };

  const handleDownload = () => {
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `${title.replace(/\s+/g, '_')}.wav`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
  }

  return (
    <div className="w-full max-w-xl mx-auto mt-8 bg-slate-800 border border-amber-500/30 rounded-2xl p-6 shadow-2xl animate-fade-in">
        <audio ref={audioRef} src={audioUrl} />

        <div className="text-center mb-6">
            <h3 className="text-2xl font-bold text-amber-100 cinzel">{title}</h3>
            <div className="flex flex-wrap justify-center gap-x-4 gap-y-1 text-amber-500/60 text-[10px] uppercase tracking-widest mt-2 font-bold">
               <span className="flex items-center gap-1"><span className="text-slate-500">VOICE:</span> {voiceLabel}</span>
               <span className="flex items-center gap-1"><span className="text-slate-500">SPEED:</span> {params.speed}X</span>
               <span className="flex items-center gap-1"><span className="text-slate-500">PITCH:</span> {params.pitch.toFixed(1)}X</span>
            </div>
        </div>

        {/* Progress Bar */}
        <div className="flex items-center gap-4 mb-6">
             <span className="text-xs text-slate-400 w-10 text-right">{formatTime(audioRef.current?.currentTime || 0)}</span>
             <input 
                type="range" 
                min="0" 
                max="100" 
                value={progress || 0} 
                onChange={handleSeek}
                className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-amber-500"
            />
            <span className="text-xs text-slate-400 w-10">{formatTime(duration)}</span>
        </div>

        {/* Controls */}
        <div className="flex items-center justify-center gap-8">
             <button 
                onClick={onReset}
                className="p-3 rounded-full text-slate-400 hover:bg-slate-700 hover:text-slate-200 transition-colors"
                title="Create New"
            >
                <RefreshCcw size={20} />
            </button>

            <button 
                onClick={togglePlay}
                className="w-16 h-16 flex items-center justify-center rounded-full bg-amber-600 hover:bg-amber-500 text-white shadow-[0_0_20px_rgba(217,119,6,0.3)] transition-all transform hover:scale-105"
            >
                {isPlaying ? <Pause fill="currentColor" /> : <Play fill="currentColor" className="ml-1" />}
            </button>

            <button 
                onClick={handleDownload}
                className="p-3 rounded-full text-slate-400 hover:bg-slate-700 hover:text-slate-200 transition-colors"
                title="Download WAV"
            >
                <Download size={20} />
            </button>
        </div>
    </div>
  );
};

