import { GoogleGenAI } from "@google/genai";
import { BibleRequest, TTSRequest } from "../types";
import { base64ToUint8Array, createWavBlob } from "../utils/audioUtils";

// Helper to split text into manageable chunks for TTS
const chunkText = (text: string, maxLength: number = 2800): string[] => {
  if (text.length <= maxLength) return [text];

  const chunks: string[] = [];
  let current = text;

  while (current.length > 0) {
    if (current.length <= maxLength) {
      chunks.push(current);
      break;
    }

    // Try to split at the last period within the limit to keep sentences intact
    let splitIndex = current.lastIndexOf('. ', maxLength);

    // Fallback to any space if no period found
    if (splitIndex === -1) {
      splitIndex = current.lastIndexOf(' ', maxLength);
    }

    // Hard split if no spaces found
    if (splitIndex === -1) {
      splitIndex = maxLength;
    }

    const chunk = current.slice(0, splitIndex + 1);
    chunks.push(chunk);

    current = current.slice(splitIndex + 1).trim();
  }

  return chunks;
};

/**
 * Maps numeric pitch/speed to natural language instructions for Gemini TTS.
 */
const getSpeechInstructions = (speed: number, pitch: number): string => {
  let speedText = "normal pace";
  if (speed <= 0.8) speedText = "slowly";
  if (speed >= 1.2) speedText = "fast";
  if (speed >= 1.5) speedText = "very fast";

  let pitchText = "normal pitch";
  if (pitch <= 0.7) pitchText = "very deep voice";
  else if (pitch <= 0.9) pitchText = "deep voice";
  else if (pitch >= 1.4) pitchText = "high-pitched voice";
  else if (pitch >= 1.1) pitchText = "high pitch";

  return `Speak ${speedText} with a ${pitchText}: `;
};

/**
 * Generates audio from a string of text using Gemini TTS.
 */
export const generateAudioFromText = async (text: string, voice: string, speed: number = 1.0, pitch: number = 1.0): Promise<Blob> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const textChunks = chunkText(text);
  const audioBuffers: Uint8Array[] = [];
  const instruction = getSpeechInstructions(speed, pitch);

  console.log(`Synthesizing with instructions: "${instruction}" and Voice: ${voice}`);

  try {
    for (let i = 0; i < textChunks.length; i++) {
      const chunk = textChunks[i];
      if (!chunk) continue;

      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{
          parts: [{ text: `${instruction}${chunk}` }]
        }],
        config: {
          responseModalities: ['AUDIO'], 
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: voice },
            },
            // Removed speakingRate and pitch as they are not supported in this config object
          },
        },
      });

      const candidate = response.candidates?.[0];
      const base64Audio = candidate?.content?.parts?.[0]?.inlineData?.data;

      if (!base64Audio) {
        if (candidate?.finishReason && candidate.finishReason !== 'STOP') {
            throw new Error(`Generation stopped for chunk ${i+1} due to: ${candidate.finishReason}`);
        }
        throw new Error(`No audio data returned for part ${i + 1}.`);
      }

      audioBuffers.push(base64ToUint8Array(base64Audio));
    }

    const totalLength = audioBuffers.reduce((acc, buf) => acc + buf.length, 0);
    const combinedPCM = new Uint8Array(totalLength);
    let offset = 0;

    for (const buf of audioBuffers) {
      combinedPCM.set(buf, offset);
      offset += buf.length;
    }

    return createWavBlob(combinedPCM, 24000);

  } catch (error: any) {
    console.error("Gemini TTS Error:", error);
    throw new Error(error.message || "Failed to generate audio.");
  }
};

export const generateBibleAudio = async (request: BibleRequest): Promise<Blob> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const textPrompt = `
    Please provide the full text of the Bible chapter: ${request.book} Chapter ${request.chapter} in the ${request.version}.

    Formatting Requirements for Text-to-Speech:
    - Output ONLY the scripture text.
    - Do NOT include verse numbers.
    - Do NOT include footnotes, cross-references, or introductions.
    - Text should be continuous and readable.

    If the requested version is restricted by copyright, provide the King James Version (KJV) instead.
  `;

  let scriptureText = '';

  try {
    const textResponse = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: textPrompt,
    });

    const candidate = textResponse.candidates?.[0];

    if (candidate) {
        if (candidate.finishReason === 'SAFETY') {
            throw new Error("Request blocked by safety filters.");
        }
        if (candidate.finishReason === 'RECITATION') {
            throw new Error("Request blocked due to copyright. Please use the King James Version (KJV).");
        }
    }

    scriptureText = textResponse.text || '';
    scriptureText = scriptureText.replace(/^```(text)?/i, '').replace(/```$/, '').trim();

    if (!scriptureText) {
        if (candidate?.content?.parts?.[0]?.text) {
             scriptureText = candidate.content.parts[0].text;
        } else {
             throw new Error(`The model returned no text.`);
        }
    }

  } catch (error: any) {
      console.error("Text Retrieval Error:", error);
      throw new Error(`Failed to retrieve scripture text: ${error.message}`);
  }

  const fullTextToSpeak = `${request.book} Chapter ${request.chapter}. ${scriptureText}`;
  return generateAudioFromText(fullTextToSpeak, request.voice, request.speed, request.pitch);
};

export const generateVoicePreview = async (voice: string, pitch: number = 1.0): Promise<Blob> => {
  const previewText = "The Lord is my shepherd; I shall not want.";
  return generateAudioFromText(previewText, voice, 1.0, pitch);
};

import React, { useState } from 'react';
import Header from './components/Header';
import BibleForm from './components/BibleForm';
import SimpleTTSForm from './components/SimpleTTSForm';
import AudioPlayer from './components/AudioPlayer';
import { BibleRequest, TTSRequest, AudioState, BibleVersion, VOICE_OPTIONS } from './types';
import { generateBibleAudio, generateAudioFromText } from './services/geminiService';
import { AlertCircle } from 'lucide-react';
import { BIBLE_DATA } from './utils/bibleData';

const App: React.FC = () => {
  const [mode, setMode] = useState<'bible' | 'simple'>('bible');
  const [formData, setFormData] = useState<BibleRequest>({
    book: '',
    chapter: '',
    version: BibleVersion.NKJV,
    voice: VOICE_OPTIONS[0].id, // 'Charon'
    speed: 1.0,
    pitch: 1.0
  });

  const [simpleData, setSimpleData] = useState<TTSRequest>({
    text: '',
    voice: VOICE_OPTIONS[0].id, // 'Charon'
    speed: 1.0,
    pitch: 1.0
  });

  const [audioState, setAudioState] = useState<AudioState>({
    isLoading: false,
    audioUrl: null,
    error: null,
    blob: null
  });
  const [currentTitle, setCurrentTitle] = useState<string>('');

  const handleBibleSubmit = async () => {
    setAudioState({ isLoading: true, audioUrl: null, error: null, blob: null });
    setCurrentTitle(`${formData.book} Chapter ${formData.chapter}`);

    try {
      const blob = await generateBibleAudio(formData);
      const url = URL.createObjectURL(blob);
      setAudioState({
        isLoading: false,
        audioUrl: url,
        error: null,
        blob: blob
      });
    } catch (err: any) {
      setAudioState({
        isLoading: false,
        audioUrl: null,
        error: err.message || "An unexpected error occurred.",
        blob: null
      });
    }
  };

  const handleSimpleSubmit = async () => {
    setAudioState({ isLoading: true, audioUrl: null, error: null, blob: null });
    setCurrentTitle(`Custom Inscription`);

    try {
      const blob = await generateAudioFromText(simpleData.text, simpleData.voice, simpleData.speed, simpleData.pitch);
      const url = URL.createObjectURL(blob);
      setAudioState({
        isLoading: false,
        audioUrl: url,
        error: null,
        blob: blob
      });
    } catch (err: any) {
      setAudioState({
        isLoading: false,
        audioUrl: null,
        error: err.message || "An unexpected error occurred.",
        blob: null
      });
    }
  };

  const handleReset = () => {
    if (audioState.audioUrl) {
      URL.revokeObjectURL(audioState.audioUrl);
    }

    if (mode === 'bible' && formData.book && formData.chapter) {
      const maxChapters = BIBLE_DATA[formData.book];
      const currentChapNum = parseInt(formData.chapter, 10);
      if (currentChapNum < maxChapters) {
        setFormData(prev => ({
          ...prev,
          chapter: String(currentChapNum + 1)
        }));
      }
    }

    setAudioState({
      isLoading: false,
      audioUrl: null,
      error: null,
      blob: null
    });
    setCurrentTitle('');
  };

  const toggleMode = () => {
      setMode(prev => prev === 'bible' ? 'simple' : 'bible');
      setAudioState({ isLoading: false, audioUrl: null, error: null, blob: null });
  };

  return (
    <div className="min-h-screen bg-[radial-gradient(ellipse_at_top,_var(--tw-gradient-stops))] from-gray-900 via-black to-black text-slate-200 flex flex-col overflow-hidden">
      <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/stardust.png')] opacity-10 pointer-events-none mix-blend-overlay"></div>

      <Header />

      <main className="flex-grow flex flex-col items-center justify-center w-full px-4 relative z-10 pb-20">
        <div className="w-full max-w-4xl mx-auto flex flex-col items-center">

          {audioState.error && (
            <div className="w-full max-w-xl mb-8 bg-red-950/40 border border-red-500/30 text-red-200 p-4 rounded-lg flex items-center gap-3 backdrop-blur-md shadow-lg animate-fade-in">
              <AlertCircle className="w-5 h-5 shrink-0" />
              <p>{audioState.error}</p>
            </div>
          )}

          {!audioState.audioUrl && (
            <div className={`w-full transition-all duration-700 transform ${audioState.isLoading ? 'opacity-40 pointer-events-none scale-95 blur-[1px]' : 'opacity-100 scale-100'}`}>
                {mode === 'bible' ? (
                    <BibleForm 
                        data={formData} 
                        onChange={setFormData}
                        onSubmit={handleBibleSubmit} 
                        onSwitchMode={toggleMode}
                        isLoading={audioState.isLoading} 
                    />
                ) : (
                    <SimpleTTSForm 
                        data={simpleData}
                        onChange={setSimpleData}
                        onSubmit={handleSimpleSubmit}
                        onSwitchMode={toggleMode}
                        isLoading={audioState.isLoading}
                    />
                )}
            </div>
          )}

          {audioState.audioUrl && audioState.blob && (
            <div className="w-full animate-fade-in-up">
              <AudioPlayer 
                  audioUrl={audioState.audioUrl} 
                  blob={audioState.blob}
                  title={currentTitle}
                  params={mode === 'bible' ? formData : simpleData}
                  onReset={handleReset}
              />
            </div>
          )}

          {audioState.isLoading && !audioState.audioUrl && (
             <div className="absolute inset-0 flex flex-col items-center justify-center z-50">
                 <div className="bg-black/40 backdrop-blur-sm p-8 rounded-2xl border border-zinc-800 shadow-2xl">
                   <p className="text-zinc-400 font-cinzel text-xl tracking-widest animate-pulse">FORGING AUDIO</p>
                   <p className="text-zinc-600 text-sm mt-3 text-center">Consulting the archives...</p>
                 </div>
             </div>
          )}
        </div>
      </main>

      <footer className="absolute bottom-4 w-full text-center text-zinc-800 text-xs tracking-widest uppercase opacity-60">
          <p>Testament of Steel • Powered by Gemini 2.5</p>
      </footer>
    </div>
  );
};

export default App;

