import React, { useState } from 'react';
import { BibleRequest, BibleVersion, VOICE_OPTIONS, SPEED_OPTIONS, VOICE_PRESETS } from '../types';
import { Volume2, Loader2, ChevronDown, PlayCircle, PauseCircle, Mic, Music, UserCircle } from 'lucide-react';
import { BIBLE_DATA } from '../utils/bibleData';
import { generateVoicePreview } from '../services/geminiService';

interface BibleFormProps {
  data: BibleRequest;
  onChange: (data: BibleRequest) => void;
  onSubmit: () => void;
  onSwitchMode: () => void;
  isLoading: boolean;
}

const BibleForm: React.FC<BibleFormProps> = ({ data, onChange, onSubmit, onSwitchMode, isLoading }) => {
  // Preview State
  const [previewLoading, setPreviewLoading] = useState(false);
  const [previewPlaying, setPreviewPlaying] = useState(false);
  const [currentPreviewAudio, setCurrentPreviewAudio] = useState<HTMLAudioElement | null>(null);

  const books = Object.keys(BIBLE_DATA);

  const handleBookChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const selectedBook = e.target.value;
    onChange({
        ...data,
        book: selectedBook,
        chapter: '' // Reset chapter when book changes
    });
  };

  const updateField = (field: keyof BibleRequest, value: any) => {
      onChange({
          ...data,
          [field]: value
      });
  };

  const handleApplyPreset = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const presetId = e.target.value;
    const preset = VOICE_PRESETS.find(p => p.id === presetId);
    if (preset) {
        onChange({
            ...data,
            voice: preset.voice,
            speed: preset.speed,
            pitch: preset.pitch
        });
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (data.book && data.chapter) {
      if (currentPreviewAudio) {
        currentPreviewAudio.pause();
        setPreviewPlaying(false);
      }
      onSubmit();
    }
  };

  const handlePreviewVoice = async (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    if (previewPlaying && currentPreviewAudio) {
      currentPreviewAudio.pause();
      setPreviewPlaying(false);
      return;
    }

    setPreviewLoading(true);

    try {
      const blob = await generateVoicePreview(data.voice, data.pitch);
      const url = URL.createObjectURL(blob);
      const audio = new Audio(url);

      audio.onended = () => {
        setPreviewPlaying(false);
        URL.revokeObjectURL(url);
      };

      audio.play();
      setCurrentPreviewAudio(audio);
      setPreviewPlaying(true);
    } catch (err) {
      console.error("Preview failed", err);
    } finally {
      setPreviewLoading(false);
    }
  };

  const chapterCount = data.book ? BIBLE_DATA[data.book] : 0;
  const chapters = Array.from({ length: chapterCount }, (_, i) => i + 1);

  const currentVoiceIsPredefined = VOICE_OPTIONS.some(v => v.id === data.voice);
  const selectValue = currentVoiceIsPredefined ? data.voice : 'custom';

  return (
    <div className="w-full max-w-xl mx-auto bg-slate-800/50 p-8 rounded-2xl border border-slate-700 shadow-xl backdrop-blur-sm">
      <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-bold text-amber-100 cinzel">Scripture Forge</h2>
          <button 
            type="button" 
            onClick={onSwitchMode}
            className="text-xs text-amber-500/60 hover:text-amber-500 transition-colors uppercase tracking-widest border border-amber-500/20 px-3 py-1 rounded-full"
          >
            Custom Inscription
          </button>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        {/* Book/Chapter Section */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pb-4 border-b border-slate-700/50">
          <div className="space-y-2 relative">
            <label htmlFor="book" className="block text-sm font-medium text-amber-100/80 uppercase tracking-wide">
              Book Name
            </label>
            <div className="relative">
              <select
                id="book"
                value={data.book}
                onChange={handleBookChange}
                className="w-full bg-slate-900/80 border border-slate-600 rounded-lg px-4 py-3 text-amber-50 focus:outline-none focus:ring-2 focus:ring-amber-500/50 appearance-none cursor-pointer transition-all"
                required
              >
                <option value="" disabled>Select Book</option>
                {books.map((b) => (
                  <option key={b} value={b}>{b}</option>
                ))}
              </select>
              <ChevronDown className="absolute right-3 top-1/2 transform -translate-y-1/2 text-slate-400 w-4 h-4 pointer-events-none" />
            </div>
          </div>

          <div className="space-y-2">
            <label htmlFor="chapter" className="block text-sm font-medium text-amber-100/80 uppercase tracking-wide">
              Chapter
            </label>
            <div className="relative">
              <select
                id="chapter"
                value={data.chapter}
                onChange={(e) => updateField('chapter', e.target.value)}
                className={`w-full bg-slate-900/80 border border-slate-600 rounded-lg px-4 py-3 text-amber-50 focus:outline-none focus:ring-2 focus:ring-amber-500/50 appearance-none cursor-pointer transition-all
                  ${!data.book ? 'opacity-50 cursor-not-allowed' : ''}`}
                required
                disabled={!data.book}
              >
                <option value="" disabled>
                  {data.book ? "Select Chapter" : "-"}
                </option>
                {chapters.map((num) => (
                  <option key={num} value={num}>{num}</option>
                ))}
              </select>
              <ChevronDown className="absolute right-3 top-1/2 transform -translate-y-1/2 text-slate-400 w-4 h-4 pointer-events-none" />
            </div>
          </div>
        </div>

        {/* Voice Persona Quick-Select */}
        <div className="space-y-2">
            <label className="block text-sm font-medium text-amber-500/80 uppercase tracking-widest flex items-center gap-2">
                <UserCircle className="w-4 h-4" />
                Voice Persona
            </label>
            <div className="relative">
                <select
                    onChange={handleApplyPreset}
                    defaultValue=""
                    className="w-full bg-amber-950/20 border border-amber-900/40 rounded-lg px-4 py-3 text-amber-200 focus:outline-none focus:ring-2 focus:ring-amber-500/30 appearance-none cursor-pointer transition-all italic text-sm"
                >
                    <option value="" disabled>Choose a pre-defined persona...</option>
                    {VOICE_PRESETS.map(p => (
                        <option key={p.id} value={p.id}>{p.label}</option>
                    ))}
                </select>
                <ChevronDown className="absolute right-3 top-1/2 transform -translate-y-1/2 text-amber-600/50 w-4 h-4 pointer-events-none" />
            </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-2">
             <label htmlFor="voice" className="block text-sm font-medium text-amber-100/80 uppercase tracking-wide">
              Voice
            </label>
            <div className="flex flex-col gap-2">
              <div className="flex gap-2">
                <div className="relative flex-grow">
                  <select
                    id="voice"
                    value={selectValue}
                    onChange={(e) => {
                        const val = e.target.value;
                        if (val === 'custom') updateField('voice', '');
                        else updateField('voice', val);
                    }}
                    className="w-full bg-slate-900/80 border border-slate-600 rounded-lg px-4 py-3 text-amber-50 appearance-none cursor-pointer transition-all focus:outline-none focus:ring-2 focus:ring-amber-500/50"
                  >
                    <optgroup label="Male Voices">
                        {VOICE_OPTIONS.filter(v => v.gender === 'Male').map((v) => (
                        <option key={v.id} value={v.id}>{v.label}</option>
                        ))}
                    </optgroup>
                    <optgroup label="Female Voices">
                        {VOICE_OPTIONS.filter(v => v.gender === 'Female').map((v) => (
                        <option key={v.id} value={v.id}>{v.label}</option>
                        ))}
                    </optgroup>
                    <option value="custom">Custom ID...</option>
                  </select>
                  <ChevronDown className="absolute right-3 top-1/2 transform -translate-y-1/2 text-slate-400 w-4 h-4 pointer-events-none" />
                </div>

                <button
                  type="button"
                  onClick={handlePreviewVoice}
                  disabled={previewLoading || !data.voice}
                  className="px-3 bg-slate-700 hover:bg-slate-600 border border-slate-600 rounded-lg text-amber-500 transition-colors flex items-center justify-center disabled:opacity-50"
                  title="Preview Voice"
                >
                  {previewLoading ? <Loader2 className="w-5 h-5 animate-spin" /> : previewPlaying ? <PauseCircle className="w-5 h-5" /> : <PlayCircle className="w-5 h-5" />}
                </button>
              </div>

              {selectValue === 'custom' && (
                  <div className="relative animate-fade-in">
                    <input 
                        type="text"
                        value={data.voice}
                        onChange={(e) => updateField('voice', e.target.value)}
                        placeholder="Voice ID..."
                        className="w-full bg-slate-800 border border-slate-500 rounded-lg px-4 py-2 text-sm text-amber-50 placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-amber-500/50"
                    />
                    <Mic className="absolute right-3 top-1/2 transform -translate-y-1/2 text-slate-500 w-4 h-4" />
                  </div>
              )}
            </div>
          </div>

          <div className="space-y-2">
            <label htmlFor="speed" className="block text-sm font-medium text-amber-100/80 uppercase tracking-wide">
              Speed
            </label>
            <div className="relative">
              <select
                id="speed"
                value={data.speed}
                onChange={(e) => updateField('speed', parseFloat(e.target.value))}
                className="w-full bg-slate-900/80 border border-slate-600 rounded-lg px-4 py-3 text-amber-50 appearance-none cursor-pointer transition-all focus:outline-none focus:ring-2 focus:ring-amber-500/50"
              >
                {SPEED_OPTIONS.map((s) => (
                  <option key={s.value} value={s.value}>{s.label}</option>
                ))}
              </select>
              <ChevronDown className="absolute right-3 top-1/2 transform -translate-y-1/2 text-slate-400 w-4 h-4 pointer-events-none" />
            </div>
          </div>
        </div>

        <div className="space-y-4 pt-2 bg-slate-900/30 p-4 rounded-xl border border-slate-700/50">
            <div className="flex justify-between items-center">
                <label className="text-sm font-medium text-amber-100/80 uppercase tracking-widest flex items-center gap-2">
                    <Music className="w-4 h-4 text-amber-500" />
                    Pitch Tuning
                </label>
                <span className="text-amber-500 font-mono text-sm font-bold bg-amber-500/10 px-2 py-0.5 rounded border border-amber-500/20">
                    {data.pitch.toFixed(1)}x
                </span>
            </div>
            <input 
                type="range"
                min="0.5"
                max="2.0"
                step="0.1"
                value={data.pitch}
                onChange={(e) => updateField('pitch', parseFloat(e.target.value))}
                className="w-full h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-amber-500 transition-all hover:accent-amber-400"
            />
        </div>

        <div className="space-y-2">
          <label htmlFor="version" className="block text-sm font-medium text-amber-100/80 uppercase tracking-wide">
            Bible Version
          </label>
          <div className="relative">
            <select
              id="version"
              value={data.version}
              onChange={(e) => updateField('version', e.target.value as BibleVersion)}
              className="w-full bg-slate-900/80 border border-slate-600 rounded-lg px-4 py-3 text-amber-50 appearance-none cursor-pointer transition-all focus:outline-none focus:ring-2 focus:ring-amber-500/50"
            >
              {Object.values(BibleVersion).map((v) => (
                <option key={v} value={v}>{v}</option>
              ))}
            </select>
            <ChevronDown className="absolute right-3 top-1/2 transform -translate-y-1/2 text-slate-400 w-4 h-4 pointer-events-none" />
          </div>
        </div>

        <button
          type="submit"
          disabled={isLoading || !data.book || !data.chapter || !data.voice}
          className={`w-full flex items-center justify-center space-x-2 py-4 rounded-lg font-bold text-lg tracking-wide transition-all duration-300 
            ${isLoading || !data.book || !data.chapter || !data.voice
              ? 'bg-slate-700 text-slate-400 cursor-not-allowed' 
              : 'bg-gradient-to-r from-amber-600 to-amber-700 hover:from-amber-500 hover:to-amber-600 text-white shadow-[0_0_20px_rgba(217,119,6,0.4)]'
            }`}
        >
          {isLoading ? (
            <>
              <Loader2 className="animate-spin w-5 h-5" />
              <span>Forging Audio...</span>
            </>
          ) : (
            <>
              <Volume2 className="w-5 h-5" />
              <span>Generate MP3</span>
            </>
          )}
        </button>
      </form>
    </div>
  );
};

