const SimpleTTSForm: React.FC<SimpleTTSFormProps> = ({ data, onChange, onSubmit, onSwitchMode, isLoading }) => {
  const [previewLoading, setPreviewLoading] = useState(false);
  const [previewPlaying, setPreviewPlaying] = useState(false);
  const [currentPreviewAudio, setCurrentPreviewAudio] = useState<HTMLAudioElement | null>(null);

  const updateField = (field: keyof TTSRequest, value: any) => {
      onChange({
          ...data,
          [field]: value
      });
  };

  const handleApplyPreset = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const presetId = e.target.value;
    const preset = VOICE_PRESETS.find(p => p.id === presetId);
    if (preset) {
        onChange({
            ...data,
            voice: preset.voice,
            speed: preset.speed,
            pitch: preset.pitch
        });
    }
  };

  const handlePreviewVoice = async (e: React.MouseEvent) => {
    e.preventDefault();
    if (previewPlaying && currentPreviewAudio) {
      currentPreviewAudio.pause();
      setPreviewPlaying(false);
      return;
    }
    setPreviewLoading(true);
    try {
      const blob = await generateVoicePreview(data.voice, data.pitch);
      const url = URL.createObjectURL(blob);
      const audio = new Audio(url);
      audio.onended = () => {
        setPreviewPlaying(false);
        URL.revokeObjectURL(url);
      };
      audio.play();
      setCurrentPreviewAudio(audio);
      setPreviewPlaying(true);
    } catch (err) {
      console.error("Preview failed", err);
    } finally {
      setPreviewLoading(false);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (data.text.trim() && data.voice) {
        if (currentPreviewAudio) {
            currentPreviewAudio.pause();
            setPreviewPlaying(false);
        }
        onSubmit();
    }
  };

  const currentVoiceIsPredefined = VOICE_OPTIONS.some(v => v.id === data.voice);
  const selectValue = currentVoiceIsPredefined ? data.voice : 'custom';

  return (
    <div className="w-full max-w-xl mx-auto bg-slate-800/50 p-8 rounded-2xl border border-slate-700 shadow-xl backdrop-blur-sm">
      <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-bold text-amber-100 cinzel">Generic Inscription</h2>
          <button 
            type="button" 
            onClick={onSwitchMode}
            className="text-xs text-amber-500/60 hover:text-amber-500 transition-colors uppercase tracking-widest border border-amber-500/20 px-3 py-1 rounded-full"
          >
            Switch to Chapters
