      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="space-y-2">
            <label className="block text-sm font-medium text-amber-100/80 uppercase tracking-wide">
                Manuscript Text
            </label>
            <div className="relative">
                <textarea
                    value={data.text}
                    onChange={(e) => updateField('text', e.target.value)}
                    placeholder="Enter words to be forged..."
                    className="w-full bg-slate-900/80 border border-slate-600 rounded-lg px-4 py-3 text-amber-50 focus:outline-none focus:ring-2 focus:ring-amber-500/50 min-h-[100px] resize-none transition-all"
