    } catch (fallbackError: any) {
        if (fallbackError.message.includes('RECITATION_BLOCK')) {
            throw new Error(`The archives for ${request.book} ${request.chapter} are heavily guarded by safety filters. Try a different book or a shorter chapter.`);
        }
        throw new Error(`Failed to retrieve scripture text: ${fallbackError.message}`);
    }
  }

  const fullTextToSpeak = `${request.book} Chapter ${request.chapter}. ${scriptureText}`;
  return generateAudioFromText(fullTextToSpeak, request.voice, request.speed, request.pitch);
};

export const generateVoicePreview = async (voice: string, pitch: number = 1.0): Promise<Blob> => {
  const previewText = "The Lord is my shepherd; I shall not want.";
  return generateAudioFromText(previewText, voice, 1.0, pitch);
};

