                title="Delete Project"
              >
                <svg className="w-4 h-4 pointer-events-none" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
              </button>
            </div>
          ))}
        </div>

        <div className="p-4 border-t border-slate-800 bg-slate-950/40 space-y-3">
           <button 
            onClick={handleOpenKeySelector}
            className={`w-full flex items-center justify-between px-4 py-3 rounded-xl border transition-all ${hasCustomKey ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-400' : 'bg-slate-800 border-slate-700 text-slate-400 hover:text-slate-200'}`}
           >
              <div className="flex items-center space-x-3">
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 7a2 2 0 012 2m4 0a6 6 0 01-7.743 5.743L11 17H9v2H7v2H4a1 1 0 01-1-1v-2.586a1 1 0 01.293-.707l5.964-5.964A6 6 0 1121 9z" /></svg>
                <span className="text-xs font-bold uppercase tracking-wider">
                  {hasCustomKey ? 'Manage Billing' : 'API Key Selection'}
                </span>
              </div>
              {hasCustomKey && <div className="w-2 h-2 bg-emerald-500 rounded-full shadow-[0_0_8px_rgba(16,185,129,0.8)]" />}
           </button>
           <p className="px-2 text-[10px] text-slate-500 leading-tight">
             Select a personal API key from a <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" className="text-indigo-400 hover:underline">paid GCP project</a> to bypass shared usage limits.
           </p>
        </div>
      </aside>

      <div className="flex-1 flex flex-col min-h-screen">
        <header className="border-b border-slate-800 bg-slate-950/80 backdrop-blur-md sticky top-0 z-50">
          <div className="max-w-7xl mx-auto px-6 h-16 flex items-center justify-between">
            <div className="flex items-center space-x-4">
              <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 hover:bg-slate-800 rounded-lg text-slate-400">
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg>
              </button>
              <div className="flex items-center space-x-3 cursor-pointer" onClick={startNewProject}>
                <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center shadow-lg">
                  <svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19V6l12-3v13M9 19c0 1.105-1.343 2-3 2s-3-.895-3-2 1.343-2 3-2 3 .895 3 2zm12-3c0 1.105-1.343 2-3 2s-3-.895-3-2 1.343-2 3-2 3 .895 3 2zM9 10l12-3" /></svg>
                </div>
                <h1 className="text-lg font-bold tracking-tight hidden sm:block">Sonic<span className="text-indigo-500">Critique</span> AI</h1>
              </div>
            </div>

            <div className="flex items-center space-x-4">
              {hasCustomKey && (
                <div className="flex items-center space-x-2 px-3 py-1 bg-emerald-500/10 text-emerald-400 rounded-full text-[10px] font-bold border border-emerald-500/20">
                  <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-pulse" />
                  <span>PERSONAL KEY ACTIVE</span>
                </div>
              )}
              {latestCritique && (
                <button 
                  onClick={() => setIsChatOpen(prev => !prev)}
                  className={`flex items-center space-x-2 px-4 py-1.5 rounded-full text-xs font-bold transition-all ${isChatOpen ? 'bg-indigo-600 text-white' : 'bg-slate-800 text-slate-300 hover:bg-slate-700'}`}
                >
                  <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path d="M2 5a2 2 0 012-2h7a2 2 0 012 2v4a2 2 0 01-2 2H9l-3 3v-3H4a2 2 0 01-2-2V5z" /></svg>
                  <span>CHAT WITH ENGINEER</span>
                </button>
              )}
            </div>
          </div>
        </header>

        <main className="flex-1 max-w-7xl mx-auto px-6 py-12 w-full">
          {status === AnalysisStatus.IDLE && (
            <div className="max-w-2xl mx-auto text-center space-y-8 animate-in zoom-in duration-500 py-12">
              <div className="space-y-4">
                <h2 className="text-4xl md:text-5xl font-extrabold text-white">Persistent <span className="text-indigo-500">Mix History</span></h2>
                <p className="text-slate-400 text-lg leading-relaxed">Start a new project or select a saved one from the sidebar. Every revision you upload is remembered, allowing the AI to track your progress.</p>
              </div>
              <div onClick={triggerUpload} className="group relative cursor-pointer p-16 rounded-3xl border-2 border-dashed border-slate-800 bg-slate-900/30 hover:bg-slate-900/50 hover:border-indigo-500/50 transition-all duration-300">
                <div className="flex flex-col items-center">
                  <div className="w-16 h-16 bg-slate-800 rounded-2xl flex items-center justify-center mb-6 group-hover:bg-indigo-600 transition-colors">
                    <svg className="w-8 h-8 text-indigo-400 group-hover:text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>
                  </div>
                  <h3 className="text-xl font-bold mb-2">Upload First Revision</h3>
                  <p className="text-slate-500 italic">"The AI engineer never forgets a frequency."</p>
                </div>
              </div>
            </div>
          )}

          {(status !== AnalysisStatus.IDLE && status !== AnalysisStatus.ERROR) && (
            <div className="space-y-12">
              {status !== AnalysisStatus.SUCCESS && (
                <div className="max-w-md mx-auto text-center space-y-6 py-24">
                  <div className="relative">
                    <div className="w-20 h-20 border-4 border-indigo-500/20 border-t-indigo-500 rounded-full animate-spin mx-auto" />
                    <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 font-bold text-indigo-500">{status === AnalysisStatus.COMPARING ? "VS" : "AI"}</div>
                  </div>
                  <h3 className="text-xl font-bold text-white mb-2">
                    {status === AnalysisStatus.UPLOADING && "Scanning Waveform..."}
                    {status === AnalysisStatus.ANALYZING_AI && "Engineer Reviewing Mix..."}
                    {status === AnalysisStatus.COMPARING && "Contextualizing Progress..."}
                  </h3>
                </div>
              )}

              {status === AnalysisStatus.SUCCESS && latestCritique && (
                <div id="analysis-report-container" className="animate-in fade-in slide-in-from-bottom-6 duration-700 space-y-12 bg-slate-950 p-6 rounded-3xl">
                  <div className="flex flex-col md:flex-row md:items-end justify-between gap-4 border-b border-slate-800 pb-8 mb-8">
                    <div>
                      <h2 className="text-3xl font-extrabold text-white mb-1">{currentSession?.name}</h2>
                      <p className="text-slate-500 font-medium">Project History: {currentSession?.critiques.length} Revisions Saved</p>
                    </div>
                    <div className="flex space-x-3 print:hidden">
                      <button onClick={triggerUpload} className="px-6 py-3 bg-emerald-600 hover:bg-emerald-500 text-white rounded-xl text-sm font-bold transition-all shadow-lg shadow-emerald-500/20 active:scale-95">Upload Next Revision</button>
                    </div>
                  </div>
                  <CritiqueSection critique={latestCritique} fileName={currentSession?.latestFileName || 'Track'} onCompare={triggerUpload} isComparison={currentSession!.critiques.length > 1} />
                  {audioBuffer ? <Spectrogram audioBuffer={audioBuffer} /> : <div className="bg-slate-900/30 p-12 rounded-2xl border border-slate-800 text-center text-slate-500 italic">Spectrogram is available for the current active upload.</div>}
                  <div className="pt-12 text-center print:hidden">
                     <button onClick={() => setIsChatOpen(true)} className="inline-flex items-center space-x-3 bg-indigo-600/10 border border-indigo-500/30 text-indigo-400 px-8 py-4 rounded-2xl hover:bg-indigo-600/20 transition-all font-bold">
                      <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M2 5a2 2 0 012-2h7a2 2 0 012 2v4a2 2 0 01-2 2H9l-3 3v-3H4a2 2 0 01-2-2V5z" /></svg>
                      <span>Ask our Engineer about this revision</span>
                    </button>
                  </div>
                </div>
              )}
            </div>
          )}

          {status === AnalysisStatus.ERROR && (
            <div className={`max-w-lg mx-auto ${isQuotaError ? 'bg-amber-950/20 border-amber-500/30' : 'bg-red-950/20 border-red-500/30'} border p-8 rounded-3xl text-center space-y-6`}>
              <h2 className={`text-xl font-bold ${isQuotaError ? 'text-amber-400' : 'text-red-400'}`}>
                {isQuotaError ? 'Daily Usage Limit Reached' : 'Analysis Failed'}
              </h2>
              <p className="text-slate-400">
                {isQuotaError 
                  ? 'The shared demo key has run out of requests for today. To continue, please select your own Gemini API key from a paid GCP project.' 
                  : error}
              </p>
              <div className="flex flex-col space-y-3">
                {isQuotaError && (
                  <button 
                    onClick={handleOpenKeySelector}
                    className="w-full py-3 bg-amber-600 hover:bg-amber-500 text-white rounded-xl font-bold transition-colors shadow-lg shadow-amber-500/20"
                  >
                    Select Personal API Key
                  </button>
                )}
                <button onClick={() => { setStatus(AnalysisStatus.IDLE); setIsQuotaError(false); }} className="w-full py-3 bg-slate-800 hover:bg-slate-700 text-white rounded-xl font-bold transition-colors">
                  Go Back
                </button>
              </div>
            </div>
          )}
        </main>
      </div>

      {chatSession && (
        <ChatInterface 
          session={chatSession} 
          isOpen={isChatOpen} 
          onClose={() => setIsChatOpen(false)} 
        />
      )}

      <input type="file" ref={globalFileInputRef} onChange={handleFileChange} className="hidden" accept="audio/*" />
    </div>
  );
};

export default App;

export interface TimestampedFeedback {
  time: string;
  issue: string;
  suggestion: string;
  studioOneTip: string;
}

export interface ThirdPartyPlugin {
  name: string;
  reason: string;
  url: string;
}

export interface LibraryPluginSuggestion {
  pluginName: string;
  application: string;
}

export interface CritiqueResult {
  overallScore: number;
  summary: string;
  tonalBalance: string;
  dynamics: string;
  stereoImage: string;
  timestampedFeedback: TimestampedFeedback[];
  generalSuggestions: string[];
  thirdPartyPlugins?: ThirdPartyPlugin[];
  libraryPluginSuggestions?: LibraryPluginSuggestion[];
  comparisonSummary?: string;
  improvements?: string[];
  remainingIssues?: string[];
  scoreChange?: number;
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
  images?: string[]; // Array of base64 encoded image strings
}

export interface Session {
  id: string;
  name: string;
  createdAt: number;
  lastModified: number;
  critiques: CritiqueResult[];
  latestFileName: string | null;
  chatHistory?: ChatMessage[]; // Added for report inclusion
}

export enum AnalysisStatus {
  IDLE = 'IDLE',
  UPLOADING = 'UPLOADING',
  GENERATING_VISUALS = 'GENERATING_VISUALS',
  ANALYZING_AI = 'ANALYZING_AI',
  COMPARING = 'COMPARING',
  SUCCESS = 'SUCCESS',
  ERROR = 'ERROR'
}

import React, { useState } from 'react';
import { CritiqueResult, TimestampedFeedback, LibraryPluginSuggestion, ChatMessage } from '../types';
import { jsPDF } from 'jspdf';
import html2canvas from 'html2canvas';

interface CritiqueSectionProps {
  critique: CritiqueResult;
  fileName: string | null;
  onCompare: () => void;
  isComparison: boolean;
  chatHistory?: ChatMessage[];
}

const FeedbackCard: React.FC<{ item: TimestampedFeedback }> = ({ item }) => (
  <div className="bg-slate-800/40 p-5 rounded-xl border-l-4 border-indigo-500 hover:bg-slate-800/60 transition-all">
    <div className="flex items-start justify-between mb-2">
      <span className="bg-indigo-600 text-white text-xs font-bold px-2 py-1 rounded">
        {item.time}
      </span>
      <div className="flex items-center space-x-2">
        <span className="text-xs text-slate-400 italic">Studio One Expert Tip</span>
      </div>
    </div>
    <h4 className="font-semibold text-slate-100 mb-1">{item.issue}</h4>
    <p className="text-slate-300 text-sm mb-4 leading-relaxed">{item.suggestion}</p>
    <div className="bg-indigo-950/30 p-3 rounded-lg border border-indigo-900/50 text-indigo-200 text-xs">
      <strong>Pro Tip:</strong> {item.studioOneTip}
    </div>
  </div>
);

const LibraryMatchCard: React.FC<{ suggestion: LibraryPluginSuggestion }> = ({ suggestion }) => (
  <div className="bg-emerald-900/10 border border-emerald-500/20 p-5 rounded-2xl hover:border-emerald-500/40 transition-all group">
    <div className="flex items-center justify-between mb-3">
      <span className="text-[10px] font-bold bg-emerald-500/20 text-emerald-400 px-2 py-1 rounded-full uppercase tracking-tighter">
        Library Match
      </span>
      <svg className="w-4 h-4 text-emerald-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
      </svg>
    </div>
    <h4 className="font-bold text-slate-100 mb-2 group-hover:text-emerald-400 transition-colors">{suggestion.pluginName}</h4>
    <p className="text-sm text-slate-400 leading-relaxed italic">
      {suggestion.application}
    </p>
  </div>
);

const CritiqueSection: React.FC<CritiqueSectionProps> = ({ critique, fileName, onCompare, isComparison, chatHistory }) => {
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);

  const getScoreColor = (score: number) => {
    if (score >= 80) return 'text-green-400';
    if (score >= 60) return 'text-yellow-400';
    return 'text-red-400';
  };

  const handleExportPdf = async () => {
    const reportElement = document.getElementById('analysis-report-container');
    if (!reportElement) return;

    setIsGeneratingPdf(true);
    try {
      const canvas = await html2canvas(reportElement, {
        scale: 2,
        backgroundColor: '#0f172a',
        logging: false,
        useCORS: true,
      });

      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF({
        orientation: 'portrait',
        unit: 'px',
        format: [canvas.width / 2, canvas.height / 2]
      });

      pdf.addImage(imgData, 'PNG', 0, 0, canvas.width / 2, canvas.height / 2);
      pdf.save(`${fileName?.replace(/\.[^/.]+$/, "") || 'track'}-analysis.pdf`);
    } catch (error) {
      console.error('Failed to generate PDF:', error);
      alert('Failed to generate PDF report. Please try again.');
    } finally {
      setIsGeneratingPdf(false);
    }
  };

  const handleExportText = () => {
    let reportText = `
SONICCRITIQUE AI - ANALYSIS REPORT
=============================================
File: ${fileName || 'Untitled Track'}
Grade: ${critique.overallScore}/100
Summary: ${critique.summary}
Tonal: ${critique.tonalBalance}
Dynamics: ${critique.dynamics}
Stereo: ${critique.stereoImage}

ENGINEER TIPS
-------------
${critique.timestampedFeedback.map(f => `[${f.time}] ${f.issue}: ${f.suggestion} (Tip: ${f.studioOneTip})`).join('\n')}

LIBRARY SUGGESTIONS
-------------------
${critique.libraryPluginSuggestions?.map(p => `- ${p.pluginName}: ${p.application}`).join('\n') || 'None'}
`.trim();

    if (chatHistory && chatHistory.length > 0) {
      reportText += `\n\nCONSULTATION CHAT HISTORY\n-------------------------\n`;
      reportText += chatHistory.map(m => `${m.role.toUpperCase()}: ${m.text}`).join('\n\n');
    }

    const blob = new Blob([reportText], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${fileName?.replace(/\.[^/.]+$/, "") || 'track'}-critique.txt`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-8">
      {/* SCORE HERO SECTION */}
      <section className="relative overflow-hidden bg-slate-900/60 border border-slate-800 rounded-3xl p-8 shadow-2xl">
        <div className="absolute top-0 right-0 p-6 flex items-center space-x-3 print:hidden">
            <button 
              onClick={handleExportText}
              className="p-2 bg-slate-800 hover:bg-slate-700 text-slate-400 hover:text-white rounded-lg transition-all"
              title="Export Text"
            >
              <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
              </svg>
            </button>

            <button 
              onClick={handleExportPdf}
              disabled={isGeneratingPdf}
              className={`flex items-center space-x-2 px-4 py-2 bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-bold rounded-lg transition-all shadow-lg active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed`}
            >
              <svg className={`w-4 h-4 ${isGeneratingPdf ? 'animate-spin' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                {isGeneratingPdf ? (
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
                ) : (
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" />
                )}
              </svg>
              <span>{isGeneratingPdf ? 'GENERATING...' : 'EXPORT PDF'}</span>
            </button>

            <button 
              onClick={onCompare}
              className="flex items-center space-x-2 px-4 py-2 bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-bold rounded-lg transition-all shadow-lg active:scale-95"
            >
              <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-3 7h3m-3 4h3m-6-4h.01M9 16h.01" />
              </svg>
              <span>UPLOAD REVISION</span>
            </button>
        </div>

        <div className="flex flex-col md:flex-row items-center md:items-start gap-8 mt-12 md:mt-0">
          <div className="relative group">
            <div className={`text-8xl md:text-9xl font-black tracking-tighter ${getScoreColor(critique.overallScore)} transition-transform duration-500 group-hover:scale-105`}>
              {critique.overallScore}
            </div>
            {isComparison && critique.scoreChange !== undefined && (
              <div className={`absolute -top-2 -right-6 px-3 py-1 rounded-full text-sm font-bold border ${critique.scoreChange >= 0 ? 'bg-green-500/10 text-green-400 border-green-500/30' : 'bg-red-500/10 text-red-400 border-red-500/30'}`}>
                {critique.scoreChange >= 0 ? '+' : ''}{critique.scoreChange}
              </div>
            )}
            <div className="text-center md:text-left text-xs font-bold text-slate-500 uppercase tracking-widest mt-2">Overall Quality Score</div>
          </div>

          <div className="flex-1 space-y-4 text-center md:text-left">
            <h2 className="text-2xl md:text-3xl font-bold text-white pr-0 md:pr-40 leading-tight">
              {isComparison ? "Version Comparison Report" : "Production Grade Summary"}
            </h2>
            <p className="text-slate-300 text-lg italic leading-relaxed">
              "{critique.summary}"
            </p>
            {isComparison && critique.comparisonSummary && (
               <p className="text-emerald-400 font-medium">
                {critique.comparisonSummary}
              </p>
            )}
          </div>
        </div>
      </section>

      {/* LIBRARY SUGGESTIONS */}
      {critique.libraryPluginSuggestions && critique.libraryPluginSuggestions.length > 0 && (
        <section className="animate-in slide-in-from-right duration-700">
           <h3 className="text-2xl font-bold mb-6 flex items-center">
            <span className="bg-emerald-500 w-2 h-8 rounded-full mr-3" />
            Library Match: Use Your Tools
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {critique.libraryPluginSuggestions.map((suggestion, idx) => (
              <LibraryMatchCard key={idx} suggestion={suggestion} />
            ))}
          </div>
        </section>
      )}

      {/* METRICS */}
      <section className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-slate-900/40 p-6 rounded-2xl border border-slate-800 text-center">
           <div className="text-xs text-slate-500 mb-1 uppercase tracking-tighter font-bold">Tonal Balance</div>
           <div className="text-lg font-medium text-slate-100">{critique.tonalBalance}</div>
        </div>
        <div className="bg-slate-900/40 p-6 rounded-2xl border border-slate-800 text-center">
           <div className="text-xs text-slate-500 mb-1 uppercase tracking-tighter font-bold">Dynamics</div>
           <div className="text-lg font-medium text-slate-100">{critique.dynamics}</div>
        </div>
        <div className="bg-slate-900/40 p-6 rounded-2xl border border-slate-800 text-center">
           <div className="text-xs text-slate-500 mb-1 uppercase tracking-tighter font-bold">Stereo Image</div>
           <div className="text-lg font-medium text-slate-100">{critique.stereoImage}</div>
        </div>
      </section>

      {/* TIMELINE FEEDBACK */}
      <section>
        <h3 className="text-2xl font-bold mb-6 flex items-center">
          <span className="bg-indigo-500 w-2 h-8 rounded-full mr-3" />
          Timeline Critique
        </h3>
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
          {critique.timestampedFeedback.map((item, idx) => (
            <FeedbackCard key={idx} item={item} />
          ))}
        </div>
      </section>

      {/* CHAT LOG FOR REPORT */}
      {chatHistory && chatHistory.length > 0 && (
        <section className="border-t border-slate-800 pt-12">
          <h3 className="text-2xl font-bold mb-6 flex items-center">
            <span className="bg-indigo-400 w-2 h-8 rounded-full mr-3" />
            Consultation Chat History
          </h3>
          <div className="space-y-4 bg-slate-900/30 p-6 rounded-3xl border border-slate-800">
            {chatHistory.map((msg, idx) => (
              <div key={idx} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                <div className={`max-w-[90%] p-4 rounded-2xl text-sm ${msg.role === 'user' ? 'bg-indigo-600/20 text-indigo-100' : 'bg-slate-800/50 text-slate-300 border border-slate-700'}`}>
                  <div className="text-[10px] uppercase font-bold mb-1 opacity-50">{msg.role === 'user' ? 'Producer' : 'AI Engineer'}</div>
                  <div className="whitespace-pre-wrap">{msg.text}</div>
                </div>
              </div>
            ))}
          </div>
        </section>
      )}
    </div>
  );
};

export default CritiqueSection;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Chat } from '@google/genai';
import { ChatMessage } from '../types';

interface ChatInterfaceProps {
  session: Chat;
  messages: ChatMessage[];
  onMessagesChange: (messages: ChatMessage[]) => void;
  isOpen: boolean;
  onClose: () => void;
}

const ChatInterface: React.FC<ChatInterfaceProps> = ({ session, messages, onMessagesChange, isOpen, onClose }) => {
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [selectedImages, setSelectedImages] = useState<string[]>([]);
  const [isProcessingImage, setIsProcessingImage] = useState(false);

  // Resizing state for the chat window itself
  const [dimensions, setDimensions] = useState({ width: 384, height: 600 });
  const [isResizing, setIsResizing] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Resize handler for the window
  const startResizing = useCallback((e: React.PointerEvent) => {
    e.preventDefault();
    setIsResizing(true);
  }, []);

  const stopResizing = useCallback(() => {
    setIsResizing(false);
  }, []);

  const resize = useCallback((e: PointerEvent) => {
    if (!isResizing || !containerRef.current) return;
    const newWidth = window.innerWidth - e.clientX - 24;
    const newHeight = window.innerHeight - e.clientY - 24;
    setDimensions({
      width: Math.max(320, Math.min(newWidth, window.innerWidth - 48)),
      height: Math.max(400, Math.min(newHeight, window.innerHeight - 48))
    });
  }, [isResizing]);

  useEffect(() => {
    if (isResizing) {
      window.addEventListener('pointermove', resize);
      window.addEventListener('pointerup', stopResizing);
    } else {
      window.removeEventListener('pointermove', resize);
      window.removeEventListener('pointerup', stopResizing);
    }
    return () => {
      window.removeEventListener('pointermove', resize);
      window.removeEventListener('pointerup', stopResizing);
    };
  }, [isResizing, resize, stopResizing]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  /**
   * Resizes and compresses an image to prevent UI freezing
   * Targets max 1280px dimension and JPEG 0.8 quality
   */
  const processAndResizeImage = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (e) => {
        const img = new Image();
        img.onload = () => {
          const canvas = document.createElement('canvas');
          let width = img.width;
          let height = img.height;
          const maxDim = 1280;

          if (width > height && width > maxDim) {
            height *= maxDim / width;
            width = maxDim;
          } else if (height > maxDim) {
            width *= maxDim / height;
            height = maxDim;
          }

          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          if (!ctx) return reject('Could not get canvas context');

          ctx.drawImage(img, 0, 0, width, height);
          // Use image/jpeg with 0.8 quality for significant file size reduction
          const compressedBase64 = canvas.toDataURL('image/jpeg', 0.8);
          resolve(compressedBase64);
        };
        img.onerror = reject;
        img.src = e.target?.result as string;
      };
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  };

  const handleImageSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files && files.length > 0) {
      setIsProcessingImage(true);
      try {
        const processed = await Promise.all(Array.from(files).map(processAndResizeImage));
        setSelectedImages(prev => [...prev, ...processed]);
      } catch (err) {
        console.error("Image processing failed:", err);
      } finally {
        setIsProcessingImage(false);
      }
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handlePaste = async (e: React.ClipboardEvent) => {
    const items = e.clipboardData.items;
    const imageFiles: File[] = [];
    for (let i = 0; i < items.length; i++) {
      if (items[i].type.indexOf('image') !== -1) {
        const file = items[i].getAsFile();
        if (file) imageFiles.push(file);
      }
    }

    if (imageFiles.length > 0) {
      setIsProcessingImage(true);
      try {
        const processed = await Promise.all(imageFiles.map(processAndResizeImage));
        setSelectedImages(prev => [...prev, ...processed]);
      } catch (err) {
        console.error("Paste processing failed:", err);
      } finally {
        setIsProcessingImage(false);
      }
    }
  };

  const removeImage = (index: number) => {
    setSelectedImages(prev => prev.filter((_, i) => i !== index));
  };

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if ((!input.trim() && selectedImages.length === 0) || isTyping || isProcessingImage) return;

    const userText = input.trim();
    const currentImages = [...selectedImages];

    setInput('');
    setSelectedImages([]);

    const newUserMessage: ChatMessage = { role: 'user', text: userText, images: currentImages.length > 0 ? currentImages : undefined };
    const updatedMessages = [...messages, newUserMessage];
    onMessagesChange(updatedMessages);
    setIsTyping(true);

    try {
      const parts: any[] = [];
      if (userText) parts.push({ text: userText });
      else if (currentImages.length > 0) parts.push({ text: "Analyze these screenshots in the context of my mix." });

      currentImages.forEach(img => {
        const base64Data = img.split(',')[1];
        const mimeType = img.split(';')[0].split(':')[1];
        parts.push({ inlineData: { data: base64Data, mimeType } });
      });

      const response = await session.sendMessageStream({ message: parts });
      let fullText = '';

      const newAiMessage: ChatMessage = { role: 'model', text: '' };
      onMessagesChange([...updatedMessages, newAiMessage]);

      for await (const chunk of response) {
        const textChunk = chunk.text || '';
        fullText += textChunk;
        onMessagesChange([...updatedMessages, { role: 'model', text: fullText }]);
      }
    } catch (error) {
      console.error('Chat error:', error);
      onMessagesChange([...updatedMessages, { role: 'model', text: 'Sorry, I encountered an error processing that request.' }]);
    } finally {
      setIsTyping(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div 
      ref={containerRef}
      style={{ 
        width: `${dimensions.width}px`, 
        height: `${dimensions.height}px`,
        touchAction: 'none'
      }}
      className={`fixed bottom-6 right-6 bg-slate-900 border ${isResizing ? 'border-indigo-500 shadow-indigo-500/20' : 'border-slate-800'} rounded-3xl shadow-2xl flex flex-col z-[100] animate-in slide-in-from-bottom-10 duration-300 transition-colors`}
    >
      {/* Resize Handle - Top Left */}
      <div 
        onPointerDown={startResizing}
        className="absolute top-0 left-0 w-8 h-8 cursor-nwse-resize z-50 flex items-center justify-center group"
      >
        <div className="w-4 h-4 border-t-2 border-l-2 border-slate-700 group-hover:border-indigo-500 rounded-tl transition-colors m-2" />
      </div>

      <div className="p-4 pl-10 border-b border-slate-800 flex items-center justify-between bg-indigo-950/20 rounded-t-3xl select-none">
        <div className="flex items-center space-x-3">
          <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center">
            <svg className="w-4 h-4 text-white" fill="currentColor" viewBox="0 0 20 20">
              <path d="M2 5a2 2 0 012-2h7a2 2 0 012 2v4a2 2 0 01-2 2H9l-3 3v-3H4a2 2 0 01-2-2V5z" />
            </svg>
          </div>
          <div>
            <h3 className="text-sm font-bold">Mixing Engineer Chat</h3>
            <p className="text-[10px] text-slate-400">Vision & Library Aware</p>
          </div>
        </div>
        <button onClick={onClose} className="text-slate-500 hover:text-white transition-colors p-1">
          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
          </svg>
        </button>
      </div>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.length === 0 && (
          <div className="text-center py-10 px-4">
            <p className="text-slate-500 text-sm">Ask about your revision or paste/upload screenshots (EQ curves, plugins, analyzer) for visual feedback!</p>
          </div>
        )}
        {messages.map((msg, idx) => (
          <div key={idx} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
            <div className={`max-w-[85%] p-3 rounded-2xl text-sm ${msg.role === 'user' ? 'bg-indigo-600 text-white rounded-tr-none' : 'bg-slate-800 text-slate-100 rounded-tl-none'}`}>
              {msg.images && msg.images.length > 0 && (
                <div className={`grid gap-2 mb-2 ${msg.images.length > 1 ? 'grid-cols-2' : 'grid-cols-1'}`}>
                  {msg.images.map((img, i) => (
                    <img key={i} src={img} alt="Attachment" className="rounded-lg w-full h-auto border border-white/10" />
                  ))}
                </div>
              )}
              <div className="whitespace-pre-wrap">{msg.text}</div>
            </div>
          </div>
        ))}
        {isTyping && messages.length > 0 && messages[messages.length-1].role === 'model' && messages[messages.length-1].text === '' && (
          <div className="flex justify-start">
            <div className="bg-slate-800 p-3 rounded-2xl rounded-tl-none flex space-x-1">
              <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
              <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce" style={{ animationDelay: '150ms' }} />
              <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce" style={{ animationDelay: '300ms' }} />
            </div>
          </div>
        )}
      </div>

      <form onSubmit={handleSend} className="p-4 border-t border-slate-800 bg-slate-900/50 rounded-b-3xl">
        {(selectedImages.length > 0 || isProcessingImage) && (
          <div className="mb-3 flex flex-wrap gap-2 max-h-32 overflow-y-auto p-1">
            {selectedImages.map((img, idx) => (
              <div key={idx} className="relative group">
                <img src={img} alt="Preview" className="w-16 h-16 object-cover rounded-lg border-2 border-indigo-500 shadow-sm" />
                <button 
                  type="button"
                  onClick={() => removeImage(idx)}
                  className="absolute -top-1.5 -right-1.5 bg-red-500 text-white rounded-full p-0.5 shadow-md hover:bg-red-600 transition-colors opacity-0 group-hover:opacity-100"
                >
                  <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
              </div>
            ))}
            {isProcessingImage && (
              <div className="w-16 h-16 bg-slate-800 rounded-lg flex items-center justify-center animate-pulse border-2 border-dashed border-slate-700">
                <svg className="w-6 h-6 text-slate-600 animate-spin" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
                </svg>
              </div>
            )}
          </div>
        )}

        <div className="flex items-center space-x-2">
          <button 
            type="button"
            disabled={isProcessingImage}
            onClick={() => fileInputRef.current?.click()}
            className={`p-2 rounded-xl border transition-all ${selectedImages.length > 0 ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-slate-800 border-slate-700 text-slate-400 hover:text-white hover:border-slate-600'} disabled:opacity-50`}
          >
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
            </svg>
          </button>

          <div className="relative flex-1">
            <input
              type="text"
              value={input}
              onPaste={handlePaste}
              disabled={isProcessingImage}
              onChange={(e) => setInput(e.target.value)}
              placeholder={isProcessingImage ? "Processing image..." : (selectedImages.length > 0 ? "Describe these..." : "Ask follow-up or paste...")}
              className="w-full bg-slate-800 border border-slate-700 rounded-xl py-2.5 px-4 pr-12 text-sm focus:outline-none focus:border-indigo-500 transition-colors disabled:opacity-50"
            />
            <button 
              type="submit"
              disabled={isTyping || isProcessingImage}
              className="absolute right-2 top-1/2 -translate-y-1/2 text-indigo-500 hover:text-indigo-400 p-1 disabled:opacity-50"
            >
              <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20">
                <path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" />
              </svg>
            </button>
          </div>
        </div>

        <input 
          type="file" 
          ref={fileInputRef} 
          onChange={handleImageSelect} 
          className="hidden" 
          accept="image/*" 
          multiple
        />
      </form>
    </div>
  );
};

export default ChatInterface;

import React, { useState, useCallback, useRef, useMemo, useEffect } from 'react';
import { AnalysisStatus, CritiqueResult, Session, ChatMessage } from './types';
import { analyzeAudio, createChatSession } from './services/geminiService';
import Spectrogram from './components/Spectrogram';
import CritiqueSection from './components/CritiqueSection';
import ChatInterface from './components/ChatInterface';

const STORAGE_KEY = 'sonic_critique_sessions';
const CURRENT_ID_KEY = 'sonic_critique_current_id';

declare global {
  /* Fix: Define AIStudio interface to match existing global definitions and resolve property type conflicts. */
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }

  interface Window {
    /* Fix: Match the expected type 'AIStudio' and use readonly modifier to align with global property definitions. */
    readonly aistudio: AIStudio;
  }
}

const App: React.FC = () => {
  const [sessions, setSessions] = useState<Session[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try { return JSON.parse(saved); } catch (e) { console.error("Failed to load sessions", e); }
    }
    return [];
  });

  const [currentSessionId, setCurrentSessionId] = useState<string | null>(() => {
    return localStorage.getItem(CURRENT_ID_KEY);
  });

  const [hasCustomKey, setHasCustomKey] = useState(false);
  const [status, setStatus] = useState<AnalysisStatus>(AnalysisStatus.IDLE);
  const [error, setError] = useState<string | null>(null);
  const [isQuotaError, setIsQuotaError] = useState(false);
  const [audioBuffer, setAudioBuffer] = useState<AudioBuffer | null>(null);
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  const globalFileInputRef = useRef<HTMLInputElement>(null);

  // Check custom key status on mount and when window gets focus
  const checkKeyStatus = useCallback(async () => {
    try {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      setHasCustomKey(hasKey);
    } catch (e) {
      console.error("Failed to check API key status", e);
    }
  }, []);

  useEffect(() => {
    checkKeyStatus();
    window.addEventListener('focus', checkKeyStatus);
    return () => window.removeEventListener('focus', checkKeyStatus);
  }, [checkKeyStatus]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(sessions));
  }, [sessions]);

  useEffect(() => {
    if (currentSessionId) localStorage.setItem(CURRENT_ID_KEY, currentSessionId);
    else localStorage.removeItem(CURRENT_ID_KEY);
  }, [currentSessionId]);

  const currentSession = useMemo(() => 
    sessions.find(s => s.id === currentSessionId) || null
  , [sessions, currentSessionId]);

  useEffect(() => {
    if (currentSession && currentSession.critiques.length > 0 && status === AnalysisStatus.IDLE) {
      setStatus(AnalysisStatus.SUCCESS);
    }
  }, [currentSession, status]);

  const latestCritique = currentSession?.critiques[currentSession.critiques.length - 1] || null;

  const chatSession = useMemo(() => {
    if (latestCritique) return createChatSession(latestCritique);
    return null;
  }, [latestCritique]);

  const handleOpenKeySelector = async () => {
    await window.aistudio.openSelectKey();
    checkKeyStatus();
  };

  const updateChatHistory = useCallback((messages: ChatMessage[]) => {
    if (!currentSessionId) return;
    setSessions(prev => prev.map(s => {
      if (s.id === currentSessionId) {
        return { ...s, chatHistory: messages, lastModified: Date.now() };
      }
      return s;
    }));
  }, [currentSessionId]);

  const createNewSession = (initialName: string): Session => {
    const newSession: Session = {
      id: crypto.randomUUID(),
      name: initialName,
      createdAt: Date.now(),
      lastModified: Date.now(),
      critiques: [],
      latestFileName: initialName,
      chatHistory: []
    };
    setSessions(prev => [newSession, ...prev]);
    setCurrentSessionId(newSession.id);
    return newSession;
  };

  const processAudioFile = useCallback(async (file: File, sessionId: string, prevCritique: CritiqueResult | null) => {
    try {
      setIsQuotaError(false);
      const isComparing = !!prevCritique;
      setStatus(isComparing ? AnalysisStatus.COMPARING : AnalysisStatus.UPLOADING);

      const reader = new FileReader();
      const base64Promise = new Promise<string>((resolve) => {
        reader.onload = () => {
          const result = reader.result as string;
          resolve(result.split(',')[1]);
        };
        reader.readAsDataURL(file);
      });

      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const arrayBuffer = await file.arrayBuffer();
      const decodedBuffer = await audioCtx.decodeAudioData(arrayBuffer);
      setAudioBuffer(decodedBuffer);

      setStatus(isComparing ? AnalysisStatus.COMPARING : AnalysisStatus.ANALYZING_AI);
      const base64Audio = await base64Promise;

      const result = await analyzeAudio(base64Audio, file.type, prevCritique || undefined);

      setSessions(prev => prev.map(s => {
        if (s.id === sessionId) {
          return {
            ...s,
            lastModified: Date.now(),
            latestFileName: file.name,
            critiques: [...s.critiques, result]
          };
        }
        return s;
      }));

      setStatus(AnalysisStatus.SUCCESS);
    } catch (err: any) {
      console.error(err);
      const isQuota = err.message?.includes('429') || err.message?.toLowerCase().includes('quota');
      setIsQuotaError(isQuota);
      setError(err.message || "An error occurred during analysis.");
      setStatus(AnalysisStatus.ERROR);
    }
  }, []);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      let targetId = currentSessionId;
      let prevCritique = latestCritique;
      if (!targetId) {
        const newSess = createNewSession(file.name);
        targetId = newSess.id;
        prevCritique = null;
      }
      processAudioFile(file, targetId, prevCritique);
      e.target.value = '';
    }
  };

  const triggerUpload = () => globalFileInputRef.current?.click();

  const deleteSession = (e: React.MouseEvent, id: string) => {
    e.stopPropagation(); e.preventDefault();
    if (window.confirm("Delete this mix project? This cannot be undone.")) {
      setSessions(prev => prev.filter(s => s.id !== id));
      if (currentSessionId === id) {
        setCurrentSessionId(null);
        setStatus(AnalysisStatus.IDLE);
        setAudioBuffer(null);
      }
    }
  };

  const startNewProject = () => {
    setCurrentSessionId(null);
    setStatus(AnalysisStatus.IDLE);
    setAudioBuffer(null);
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-50 flex relative">
      <aside className={`bg-slate-900 border-r border-slate-800 transition-all duration-300 flex flex-col z-40 ${isSidebarOpen ? 'w-72' : 'w-0 overflow-hidden'}`}>
        <div className="p-6 border-b border-slate-800 flex items-center justify-between whitespace-nowrap">
          <h2 className="font-bold text-slate-400 text-xs tracking-widest uppercase">Mix Projects</h2>
          <button onClick={startNewProject} className="p-2 hover:bg-slate-800 rounded-lg text-indigo-400 transition-colors" title="New Project">
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
          </button>
        </div>

        <div className="flex-1 overflow-y-auto py-4">
          {sessions.length === 0 && (
            <div className="px-6 py-10 text-center text-slate-600 italic text-sm">No saved projects yet.</div>
          )}
          {sessions.map(s => (
            <div 
              key={s.id}
              onClick={() => {
                setCurrentSessionId(s.id);
                setStatus(s.critiques.length > 0 ? AnalysisStatus.SUCCESS : AnalysisStatus.IDLE);
                setAudioBuffer(null);
              }}
              className={`px-6 py-4 cursor-pointer border-l-4 transition-all hover:bg-slate-800/50 group flex items-center justify-between ${currentSessionId === s.id ? 'bg-indigo-600/10 border-indigo-500' : 'border-transparent'}`}
            >
              <div className="flex-1 truncate mr-2">
                <div className="font-bold text-sm truncate">{s.name}</div>
                <div className="text-[10px] text-slate-500 flex items-center mt-1">
                  <span>{new Date(s.lastModified).toLocaleDateString()}</span>
                  <span className="mx-2">•</span>
                  <span>{s.critiques.length} revs</span>
                </div>
              </div>
              <button 
                type="button"
                onClick={(e) => deleteSession(e, s.id)}
                className="opacity-0 group-hover:opacity-40 hover:!opacity-100 p-1.5 hover:text-red-400 hover:bg-red-400/10 rounded-lg transition-all"
                title="Delete Project"
              >
                <svg className="w-4 h-4 pointer-events-none" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
              </button>
            </div>
          ))}
        </div>

        <div className="p-4 border-t border-slate-800 bg-slate-950/40 space-y-3">
           <button 
            onClick={handleOpenKeySelector}
            className={`w-full flex items-center justify-between px-4 py-3 rounded-xl border transition-all ${hasCustomKey ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-400' : 'bg-slate-800 border-slate-700 text-slate-400 hover:text-slate-200'}`}
           >
              <div className="flex items-center space-x-3">
