                  Go Back
                </button>
              </div>
            </div>
          )}
        </main>
      </div>

      {chatSession && (
        <ChatInterface 
          session={chatSession} 
          messages={currentSession?.chatHistory || []}
          onMessagesChange={updateChatHistory}
          isOpen={isChatOpen} 
          onClose={() => setIsChatOpen(false)} 
        />
      )}

      <input type="file" ref={globalFileInputRef} onChange={handleFileChange} className="hidden" accept="audio/*" />
    </div>
  );
};

