};

/**
 * Utility for exponential backoff retries
 */
async function withRetry<T>(fn: () => Promise<T>, maxRetries = 3): Promise<T> {
  let lastError: any;
  for (let i = 0; i < maxRetries; i++) {
    try {
      return await fn();
    } catch (err: any) {
      lastError = err;
      const status = err?.status || (err?.message?.includes('500') ? 500 : 0);

      // Retry on internal errors or rate limits
      if (status === 500 || status === 429 || err?.message?.includes('INTERNAL')) {
        const delay = Math.pow(2, i) * 1000 + Math.random() * 1000;
        console.warn(`Gemini API error (Attempt ${i + 1}/${maxRetries}). Retrying in ${Math.round(delay)}ms...`, err);
        await new Promise(resolve => setTimeout(resolve, delay));
        continue;
      }
      throw err; // Don't retry on other errors
    }
  }
  throw lastError;
}

const getAIClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API Key is missing. Please ensure a key is selected.");
  return new GoogleGenAI({ apiKey });
};

export const analyzeAudio = async (base64Audio: string, mimeType: string, previousCritique?: CritiqueResult): Promise<CritiqueResult> => {
  return withRetry(async () => {
    const ai = getAIClient();

    let prompt = "Analyze this track's mixing and mastering. Be technical.";
    let systemInstruction = BASE_SYSTEM_INSTRUCTION;

    if (previousCritique) {
      systemInstruction += `\nPrevious Score: ${previousCritique.overallScore}. Compare this new version.`;
      prompt = "Compare this revision to the previous one. Did it improve?";
    }

    // Using gemini-3-flash-preview as it's typically more stable for complex JSON + Audio input during preview
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Audio, mimeType: mimeType } },
          { text: prompt }
        ],
      },
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: CRITIQUE_SCHEMA,
        // Disable thinking budget to reduce the chance of 500 Internal errors during complex audio processing
        thinkingConfig: { thinkingBudget: 0 }
      }
    });

    try {
      const text = response.text || '{}';
      return JSON.parse(text) as CritiqueResult;
    } catch (error) {
      console.error("Failed to parse Gemini response:", error);
      throw new Error("The AI provided an invalid response format.");
    }
  });
};

export const createChatSession = (critique: CritiqueResult): Chat => {
  const ai = getAIClient();
  return ai.chats.create({
    model: 'gemini-3-flash-preview',
    config: {
      systemInstruction: `You are a world-class mixing engineer. User library: ${USER_VST_LIBRARY}.
      Context: Score ${critique.overallScore}, Summary: ${critique.summary}.`,
    },
  });
};

import React, { useState, useCallback, useRef, useMemo, useEffect } from 'react';
import { AnalysisStatus, CritiqueResult, Session, ChatMessage } from './types';
import { analyzeAudio, createChatSession } from './services/geminiService';
import Spectrogram from './components/Spectrogram';
import CritiqueSection from './components/CritiqueSection';
import ChatInterface from './components/ChatInterface';

const STORAGE_KEY = 'sonic_critique_sessions';
const CURRENT_ID_KEY = 'sonic_critique_current_id';

declare global {
  /* Fix: Define AIStudio interface to match existing global definitions and resolve property type conflicts. */
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }

  interface Window {
    /* Fix: Added readonly modifier to match the existing global Window declaration for aistudio and resolve "All declarations must have identical modifiers" error. */
    readonly aistudio: AIStudio;
  }
}

const App: React.FC = () => {
  const [sessions, setSessions] = useState<Session[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try { return JSON.parse(saved); } catch (e) { console.error("Failed to load sessions", e); }
    }
    return [];
  });

  const [currentSessionId, setCurrentSessionId] = useState<string | null>(() => {
    return localStorage.getItem(CURRENT_ID_KEY);
  });

  const [hasCustomKey, setHasCustomKey] = useState(false);
  const [status, setStatus] = useState<AnalysisStatus>(AnalysisStatus.IDLE);
  const [error, setError] = useState<string | null>(null);
  const [isQuotaError, setIsQuotaError] = useState(false);
  const [audioBuffer, setAudioBuffer] = useState<AudioBuffer | null>(null);
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  const globalFileInputRef = useRef<HTMLInputElement>(null);

  // Check custom key status on mount and when window gets focus
  const checkKeyStatus = useCallback(async () => {
    try {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      setHasCustomKey(hasKey);
    } catch (e) {
      console.error("Failed to check API key status", e);
    }
  }, []);

  useEffect(() => {
    checkKeyStatus();
    window.addEventListener('focus', checkKeyStatus);
    return () => window.removeEventListener('focus', checkKeyStatus);
  }, [checkKeyStatus]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(sessions));
  }, [sessions]);

  useEffect(() => {
    if (currentSessionId) localStorage.setItem(CURRENT_ID_KEY, currentSessionId);
    else localStorage.removeItem(CURRENT_ID_KEY);
  }, [currentSessionId]);

  const currentSession = useMemo(() => 
    sessions.find(s => s.id === currentSessionId) || null
  , [sessions, currentSessionId]);

  useEffect(() => {
    if (currentSession && currentSession.critiques.length > 0 && status === AnalysisStatus.IDLE) {
      setStatus(AnalysisStatus.SUCCESS);
    }
  }, [currentSession, status]);

  const latestCritique = currentSession?.critiques[currentSession.critiques.length - 1] || null;

  const chatSession = useMemo(() => {
    if (latestCritique) return createChatSession(latestCritique);
    return null;
  }, [latestCritique]);

  const handleOpenKeySelector = async () => {
    await window.aistudio.openSelectKey();
    // Fix: Assume the key selection was successful after triggering openSelectKey() per instructions to avoid race conditions.
    setHasCustomKey(true);
    checkKeyStatus();
  };

  const updateChatHistory = useCallback((messages: ChatMessage[]) => {
    if (!currentSessionId) return;
    setSessions(prev => prev.map(s => {
      if (s.id === currentSessionId) {
        return { ...s, chatHistory: messages, lastModified: Date.now() };
      }
      return s;
    }));
  }, [currentSessionId]);

  const createNewSession = (initialName: string): Session => {
    const newSession: Session = {
      id: crypto.randomUUID(),
      name: initialName,
      createdAt: Date.now(),
      lastModified: Date.now(),
      critiques: [],
      latestFileName: initialName,
      chatHistory: []
    };
    setSessions(prev => [newSession, ...prev]);
    setCurrentSessionId(newSession.id);
    return newSession;
  };

  const processAudioFile = useCallback(async (file: File, sessionId: string, prevCritique: CritiqueResult | null) => {
    try {
      setIsQuotaError(false);
      const isComparing = !!prevCritique;
      setStatus(isComparing ? AnalysisStatus.COMPARING : AnalysisStatus.UPLOADING);

      const reader = new FileReader();
      const base64Promise = new Promise<string>((resolve) => {
        reader.onload = () => {
          const result = reader.result as string;
          resolve(result.split(',')[1]);
        };
        reader.readAsDataURL(file);
      });

      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const arrayBuffer = await file.arrayBuffer();
      const decodedBuffer = await audioCtx.decodeAudioData(arrayBuffer);
      setAudioBuffer(decodedBuffer);

      setStatus(isComparing ? AnalysisStatus.COMPARING : AnalysisStatus.ANALYZING_AI);
      const base64Audio = await base64Promise;

      const result = await analyzeAudio(base64Audio, file.type, prevCritique || undefined);

      setSessions(prev => prev.map(s => {
        if (s.id === sessionId) {
          return {
            ...s,
            lastModified: Date.now(),
            latestFileName: file.name,
            critiques: [...s.critiques, result]
          };
        }
        return s;
      }));

      setStatus(AnalysisStatus.SUCCESS);
    } catch (err: any) {
      console.error(err);
      // Fix: If the request fails with an error message containing "Requested entity was not found.", reset key state and prompt for re-selection.
      if (err.message?.includes("Requested entity was not found.")) {
        setHasCustomKey(false);
        window.aistudio.openSelectKey().then(() => setHasCustomKey(true));
      }

      const isQuota = err.message?.includes('429') || err.message?.toLowerCase().includes('quota');
      setIsQuotaError(isQuota);
      setError(err.message || "An error occurred during analysis.");
      setStatus(AnalysisStatus.ERROR);
    }
  }, []);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      let targetId = currentSessionId;
      let prevCritique = latestCritique;
      if (!targetId) {
        const newSess = createNewSession(file.name);
        targetId = newSess.id;
        prevCritique = null;
      }
      processAudioFile(file, targetId, prevCritique);
      e.target.value = '';
    }
  };

  const triggerUpload = () => globalFileInputRef.current?.click();

  const deleteSession = (e: React.MouseEvent, id: string) => {
    e.stopPropagation(); e.preventDefault();
    if (window.confirm("Delete this mix project? This cannot be undone.")) {
      setSessions(prev => prev.filter(s => s.id !== id));
      if (currentSessionId === id) {
        setCurrentSessionId(null);
        setStatus(AnalysisStatus.IDLE);
        setAudioBuffer(null);
      }
    }
  };

  const startNewProject = () => {
    setCurrentSessionId(null);
    setStatus(AnalysisStatus.IDLE);
    setAudioBuffer(null);
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-50 flex relative">
      <aside className={`bg-slate-900 border-r border-slate-800 transition-all duration-300 flex flex-col z-40 ${isSidebarOpen ? 'w-72' : 'w-0 overflow-hidden'}`}>
        <div className="p-6 border-b border-slate-800 flex items-center justify-between whitespace-nowrap">
          <h2 className="font-bold text-slate-400 text-xs tracking-widest uppercase">Mix Projects</h2>
          <button onClick={startNewProject} className="p-2 hover:bg-slate-800 rounded-lg text-indigo-400 transition-colors" title="New Project">
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
          </button>
        </div>

        <div className="flex-1 overflow-y-auto py-4">
          {sessions.length === 0 && (
            <div className="px-6 py-10 text-center text-slate-600 italic text-sm">No saved projects yet.</div>
          )}
          {sessions.map(s => (
            <div 
              key={s.id}
              onClick={() => {
                setCurrentSessionId(s.id);
                setStatus(s.critiques.length > 0 ? AnalysisStatus.SUCCESS : AnalysisStatus.IDLE);
                setAudioBuffer(null);
              }}
              className={`px-6 py-4 cursor-pointer border-l-4 transition-all hover:bg-slate-800/50 group flex items-center justify-between ${currentSessionId === s.id ? 'bg-indigo-600/10 border-indigo-500' : 'border-transparent'}`}
            >
              <div className="flex-1 truncate mr-2">
                <div className="font-bold text-sm truncate">{s.name}</div>
                <div className="text-[10px] text-slate-500 flex items-center mt-1">
                  <span>{new Date(s.lastModified).toLocaleDateString()}</span>
                  <span className="mx-2">•</span>
                  <span>{s.critiques.length} revs</span>
                </div>
              </div>
              <button 
                type="button"
                onClick={(e) => deleteSession(e, s.id)}
                className="opacity-0 group-hover:opacity-40 hover:!opacity-100 p-1.5 hover:text-red-400 hover:bg-red-400/10 rounded-lg transition-all"
                title="Delete Project"
              >
                <svg className="w-4 h-4 pointer-events-none" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
              </button>
            </div>
          ))}
        </div>

        <div className="p-4 border-t border-slate-800 bg-slate-950/40 space-y-3">
           <button 
            onClick={handleOpenKeySelector}
            className={`w-full flex items-center justify-between px-4 py-3 rounded-xl border transition-all ${hasCustomKey ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-400' : 'bg-slate-800 border-slate-700 text-slate-400 hover:text-slate-200'}`}
           >
              <div className="flex items-center space-x-3">
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 7a2 2 0 012 2m4 0a6 6 0 01-7.743 5.743L11 17H9v2H7v2H4a1 1 0 01-1-1v-2.586a1 1 0 01.293-.707l5.964-5.964A6 6 0 1121 9z" /></svg>
                <span className="text-xs font-bold uppercase tracking-wider">
                  {hasCustomKey ? 'Manage Billing' : 'API Key Selection'}
                </span>
              </div>
              {hasCustomKey && <div className="w-2 h-2 bg-emerald-500 rounded-full shadow-[0_0_8px_rgba(16,185,129,0.8)]" />}
