import JSZip from 'jszip';
import { SessionBlueprint, SessionTrack } from '../types';

/**
 * Generates a Studio One compatible XML string for a song.
 * This is a simplified representation of the complex .song XML structure.
 */
function generateSongXml(name: string, blueprint: SessionBlueprint): string {
  const tracksXml = blueprint.tracks.map((track, i) => `
    <AudioTrack name="${track.name}" id="${i + 100}" color="0x3498db">
      <InsertList>
        ${track.inserts.map((plugin, pi) => `
          <Plugin name="${plugin}" id="${pi + 1000}" active="1" />
        `).join('')}
      </InsertList>
      ${track.sends ? track.sends.map(send => `
        <Send target="${send.target}" level="${send.level}" />
      `).join('') : ''}
    </AudioTrack>
  `).join('');

  const masterInserts = blueprint.masterBus.inserts.map((plugin, i) => `
    <Plugin name="${plugin}" id="${i + 5000}" active="1" />
  `).join('');

  return `<?xml version="1.0" encoding="UTF-8"?>
<StudioOneSong version="1.0" name="${name}">
  <ProjectSettings sampleRate="44100" bitDepth="24" />
  <TrackList>
    ${tracksXml}
  </TrackList>
  <Mixer>
    <MasterBus name="Master">
      <InsertList>
        ${masterInserts}
      </InsertList>
    </MasterBus>
  </Mixer>
</StudioOneSong>`;
}

export async function createStudioOneSession(
  name: string, 
  blueprint: SessionBlueprint, 
  audioBlob: Blob,
  audioFileName: string
): Promise<Blob> {
  const zip = new JSZip();

  // 1. Add the metadata/project XML
  const songXml = generateSongXml(name, blueprint);
  zip.file('Song.xml', songXml);

  // 2. Add the Media folder and the uploaded track
  const mediaFolder = zip.folder('Media');
  if (mediaFolder) {
    mediaFolder.file(audioFileName, audioBlob);
  }

  // 3. Dummy folders to match Studio One expected hierarchy
  zip.folder('Devices');
  zip.folder('History');

  // 4. Generate the zip blob
  const content = await zip.generateAsync({ type: 'blob' });

  // Studio One .song files are essentially renamed zip archives
  return content;
}

