          </h3>
          <div className="text-[10px] font-bold text-slate-500 bg-slate-800 px-3 py-1 rounded-full uppercase">DAW Optimization Mapping</div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {critique.sessionBlueprint.tracks.map((track, idx) => (
